  'Oito2Calendar': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A month grid that picks a date, or a range of dates when\n[onRangeSelected] is set.\n\nThe header changes the month. The grid takes the focus as a whole: the\narrow keys move by a day or a week, Home and End to the start and end\nof the week, Page Up and Page Down by a month (a year with Shift), and\nEnter or Space picks the focused day. A range takes two picks; the\nsecond may come before the first. Days outside [firstDate] and\n[lastDate], or refused by [selectableDayPredicate], can\'t be picked.\nWeek numbers follow ISO 8601.', signature: '', constructors: [ApiConstructor(name: 'Oito2Calendar', doc: 'Creates a calendar.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'firstDate', type: 'DateTime', isRequired: true, isNamed: true, defaultValue: '', doc: 'The earliest date that can be picked.'), ApiParameter(name: 'lastDate', type: 'DateTime', isRequired: true, isNamed: true, defaultValue: '', doc: 'The latest date that can be picked.'), ApiParameter(name: 'selectedDate', type: 'DateTime?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The picked date, in single mode.'), ApiParameter(name: 'onDateSelected', type: 'ValueChanged<DateTime>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with a picked date, in single mode.'), ApiParameter(name: 'selectedRange', type: 'DateTimeRange<DateTime>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The picked range, in range mode.'), ApiParameter(name: 'onRangeSelected', type: 'ValueChanged<DateTimeRange<DateTime>>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with a completed range; setting it turns on range mode.'), ApiParameter(name: 'initialMonth', type: 'DateTime?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The month shown first; defaults to the month of the selection or of\ntoday, kept within [firstDate] and [lastDate].'), ApiParameter(name: 'selectableD