  'Oito2Carousel': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A row of pages shown one at a time, with previous and next buttons and\nan [Oito2PageIndicator] below.\n\nPages change by the buttons, the dots, the Left and Right arrow keys\n(swapped in right-to-left text) while the carousel has focus (it takes focus as a whole and shows the\nfocus ring), or a swipe (also with a mouse). The buttons and arrows\nwrap around when [loop] is true, jumping straight to the other end.\nAutomatic scrolling comes from an [Oito2CarouselController].', signature: '', constructors: [ApiConstructor(name: 'Oito2Carousel', doc: 'Creates a carousel.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'children', type: 'List<Widget>', isRequired: true, isNamed: true, defaultValue: '', doc: 'The pages.'), ApiParameter(name: 'controller', type: 'Oito2CarouselController?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The controller; one without automatic scrolling is created when null.'), ApiParameter(name: 'height', type: 'double', isRequired: false, isNamed: true, defaultValue: '240', doc: 'The height of the pages.'), ApiParameter(name: 'navigationControls', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether previous and next buttons sit over the pages.'), ApiParameter(name: 'pageIndicator', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether an [Oito2PageIndicator] sits below the pages.'), ApiParameter(name: 'loop', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether going past the last page returns to the first, and back.'), ApiParameter(name: 'onPageChanged', type: 'ValueChanged<int>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with the new page index.')])], properties: [], methods: [], values: []),
  'Oito2CarouselController': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'Controls an [Oito2Carousel]: the current page, page changes and\nautomatic scrolling.\n\nWith [autoScroll], the carousel moves to the next page every\n[autoScrollInterval], wrapping to the first, while no pointer hovers it\nand nothing inside it has focus. It never scrolls by itself when\nanimations are disabled.', signature: '', constructors: [ApiConstructor(name: 'Oito2CarouselController', doc: 'Creates a carousel controller.', isConst: false, isFactory: false, parameters: [ApiParameter(name: 'initialPage', type: 'int', isRequired: false, isNamed: true, defaultValue: '0', doc: ''), ApiParameter(name: 'viewportFraction', type: 'double', isRequired: false, isNamed: true, defaultValue: '1.0', doc: ''), ApiParameter(name: 'autoScroll', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether the carousel advances by itself.'), ApiParameter(name: 'autoScrollInterval', type: 'Duration', isRequired: false, isNamed: true, defaultValue: 'const Duration(seconds: 4)', doc: 'The time each page stays before the next one when [autoScroll].'), ApiParameter(name: 'animationDuration', type: 'Duration', isRequired: false, isNamed: true, defaultValue: 'const Duration(milliseconds: 400)', doc: 'The duration of page changes.'), ApiParameter(name: 'animationCurve', type: 'Curve', isRequired: false, isNamed: true, defaultValue: 'Curves.easeInOutCubic', doc: 'The curve of page changes.')])], properties: [ApiMember(name: 'currentPage', signature: 'int', doc: 'The current page, rounded; the initial page while no carousel is\nattached.')], methods: [ApiMember(name: 'goTo', signature: 'goTo(int index, bool animate) → Future<void>', doc: 'Animates to page [index], or jumps there when [animate] is false.\n\nThe returned future completes when the change ends; it does nothing\nwhile no carousel is attached.')], values: []),
