  'Oito2Checkbox': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A check box painted in the oito2 style.\n\nThe box has a 1.5-pixel `outline` border while unchecked and fills with\nthe text-safe primary tone when checked, drawing the check mark as it\nfills. With [tristate], a null [value] shows a dash (the mixed state)\nand a tap cycles unchecked → checked → mixed. Space and Enter toggle it\nwhile focused, and the focus ring shows in keyboard navigation.\n\nThe box is 20 pixels on pointer platforms, in a 34-pixel target, and\n24 pixels on touch platforms, in a 48-pixel target.', signature: '', constructors: [ApiConstructor(name: 'Oito2Checkbox', doc: 'Creates a check box.\n\nThrows an [AssertionError] in debug builds when [value] is null and\n[tristate] is false.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'value', type: 'bool?', isRequired: true, isNamed: true, defaultValue: '', doc: 'Whether the box is checked; null is the mixed state of a [tristate]\nbox.'), ApiParameter(name: 'onChanged', type: 'ValueChanged<bool?>?', isRequired: true, isNamed: true, defaultValue: '', doc: 'Called with the next value; null disables the box.'), ApiParameter(name: 'tristate', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether a tap cycles through the mixed state.'), ApiParameter(name: 'focusNode', type: 'FocusNode?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The focus node; one is created when null.'), ApiParameter(name: 'autofocus', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether the box takes focus when first shown.'), ApiParameter(name: 'semanticLabel', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The accessibility label, when no surrounding label provides one.')])], properties: [], methods: [], values: []),
  'Oito2CheckboxListTile': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A [ListTile] with an [Oito2Checkbox]; tapping the tile toggles it.', signature: '', constructors: [ApiConstructor(name: 'Oito2CheckboxListTile', doc: 'Creates a check box list tile.\n\nThe check box throws an [AssertionError] in debug builds when [value]\nis null and [tristate] is false.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'value', type: 'bool?', isRequired: true, isNamed: true, defaultValue: '', doc: 'Whether the box is checked; null is the mixed state of a [tristate]\nbox.'), ApiParameter(name: 'onChanged', type: 'ValueChanged<bool?>?', isRequired: true, isNamed: true, defaultValue: '', doc: 'Called with the next value; null disables the tile.'), ApiParameter(name: 'title', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The primary text.'), ApiParameter(name: 'subtitle', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The secondary text.'), ApiParameter(name: 'secondary', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'A widget on the side opposite the check box, such as an icon.'), ApiParameter(name: 'tristate', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether a tap cycles through the mixed state.'), ApiParameter(name: 'controlAffinity', type: 'Oito2ControlAffinity', isRequired: false, isNamed: true, defaultValue: 'Oito2ControlAffinity.platform', doc: 'Where the check box sits; [Oito2ControlAffinity.platform] is leading.'), ApiParameter(name: 'contentPadding', type: 'EdgeInsetsGeometry?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Space around the tile content.'), ApiParameter(name: 'focusNode', type: 'FocusNode?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The focus node of the tile; one is created when null.'), ApiParameter(name: 'autofocus', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether the tile takes focus when first shown.')])], properties: [], methods: [], values: []),
