  'Oito2ChoiceChipBar': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A bar of [ChoiceChip]s for picking one or more filters, shaped by the\nchip theme unless [shape] is given.\n\nA selected chip shows the secondary container fill and, with\n[showCheckmark], a check mark before its label.\n\nIn the [Oito2ChoiceChipBarStyle.row] style the chips scroll\nhorizontally, and arrow buttons and a soft edge shadow appear only on\nthe sides with hidden chips.', signature: '', constructors: [ApiConstructor(name: 'Oito2ChoiceChipBar', doc: 'Creates a choice chip bar.\n\nThrows an [AssertionError] in debug builds when [labels] and\n[isSelected] differ in length.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'labels', type: 'List<Widget>', isRequired: true, isNamed: true, defaultValue: '', doc: 'The chip labels, usually [Text]s.'), ApiParameter(name: 'isSelected', type: 'List<bool>', isRequired: true, isNamed: true, defaultValue: '', doc: 'Whether each chip is selected, in the order of [labels].'), ApiParameter(name: 'onSelected', type: 'ValueChanged<int>?', isRequired: true, isNamed: true, defaultValue: '', doc: 'Called with the index of the activated chip; null disables the bar.'), ApiParameter(name: 'style', type: 'Oito2ChoiceChipBarStyle', isRequired: false, isNamed: true, defaultValue: 'Oito2ChoiceChipBarStyle.row', doc: 'How chips that don\'t fit are laid out.'), ApiParameter(name: 'spacing', type: 'double', isRequired: false, isNamed: true, defaultValue: 'Oito2Spacing.sm', doc: 'The space between chips, and between rows in the wrap style.'), ApiParameter(name: 'scrollStep', type: 'double', isRequired: false, isNamed: true, defaultValue: '200', doc: 'The distance, in logical pixels, one arrow button press scrolls.'), ApiParameter(name: 'previousLabel', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The tooltip and accessibility label of the backward arrow; defaults\nto [Oito2Localizations.scrollBack].'), ApiParameter(name: 'nextLabel', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The tooltip and accessibility label of the forward arrow; defaults\nto [Oito2Localizations.scrollForward].'), ApiParameter(name: 'showCheckmark', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether a selected chip shows a check mark; without it only the fill\nmarks the selection.'), ApiParameter(name: 'shape', type: 'OutlinedBorder?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The outline of the chips, such as a `StadiumBorder` for pills; the\nchip theme\'s rounded rectangle when null.')])], properties: [], methods: [], values: []),
  'Oito2ChoiceChipBarStyle': ApiEntry(kind: 'enum', package: 'oito2_ui', doc: 'How an [Oito2ChoiceChipBar] lays out chips that don\'t fit.', signature: '', constructors: [], properties: [], methods: [], values: [ApiMember(name: 'row', signature: '', doc: 'One scrollable row with arrow buttons at the edges that overflow.'), ApiMember(name: 'wrap', signature: '', doc: 'Several rows that wrap.')]),
  'Oito2ChromeColors': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'Colors of the structural window chrome: the page background, a narrow\nsidebar column, a wider mainbar panel, the title bar and modal surfaces.\n\n[Oito2ChromeColors.fromColorScheme] takes them from the Material 3\nsurface container roles, so the same rule holds in every scheme.', signature: '', constructors: [ApiConstructor(name: 'Oito2ChromeColors', doc: 'Creates chrome colors from explicit values.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'background', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: 'The page background.'), ApiParameter(name: 'sidebar', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: 'A narrow sidebar column, such as an icon rail.'), ApiParameter(name: 'mainbar', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: 'A wider mainbar panel, such as a file list or a master list.'), ApiParameter(name: 'titleBar', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: 'The window title bar.'), ApiParameter(name: 'dialog', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: 'Dialogs, bottom sheets and drawers.')]), ApiConstructor(name: 'Oito2ChromeColors.fromColorScheme', doc: 'Takes the chrome colors from the surface roles of [colorScheme],\nusing [background] as the page background.\n\n- The mainbar is `surfaceContainerHighest`, moved in lightness when\n  needed until it reaches [minimumStep] contrast against the page\n  background.\n- The sidebar is `surfaceContainer`, moved in lightness when needed\n  until it reaches [minimumStep] contrast against both the page\n  background and the mainbar, so the three stay apart even when a\n  scheme\'s background sits inside its container range.\n- The title bar is [titleBar] when given, otherwise\n  `surfaceContainer`.\n- Dialogs, sheets and drawers use `surface` in a light scheme and\n  `surfaceContainerHigh` in a