  'Oito2CircularProgressIndicator': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A circular progress indicator painted in the oito2 style.\n\nWith a [value] from 0 to 1, a ring fills clockwise from the top over\nthe track. Without one, an arc of changing length spins without a\ntrack; when animations are disabled it stays still. The ring and its\nround ends are filled shapes, so they render smoothly with every\nFlutter renderer.\n\nColors and thickness default to the theme\'s\n[Oito2ProgressIndicatorThemeData].', signature: '', constructors: [ApiConstructor(name: 'Oito2CircularProgressIndicator', doc: 'Creates a circular progress indicator.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'value', type: 'double?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The progress from 0 to 1, or null for indeterminate progress.'), ApiParameter(name: 'size', type: 'double', isRequired: false, isNamed: true, defaultValue: '32', doc: 'The diameter.'), ApiParameter(name: 'strokeWidth', type: 'double?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The ring thickness.'), ApiParameter(name: 'color', type: 'Color?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The progress color.'), ApiParameter(name: 'trackColor', type: 'Color?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The track color of determinate progress.'), ApiParameter(name: 'semanticsLabel', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The accessibility label, such as what is loading.'), ApiParameter(name: 'semanticsValue', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The accessibility value; defaults to the percentage of [value].')])], properties: [], methods: [], values: []),
  'Oito2CloseButton': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'An [Oito2IconButton] that closes: an "x" with the localized "Close"\ntooltip. By default it pops the closest [Navigator] route.', signature: '', constructors: [ApiConstructor(name: 'Oito2CloseButton', doc: 'Creates a close button.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'onPressed', type: 'VoidCallback?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called when the button is pressed; defaults to popping the current\nroute.'), ApiParameter(name: 'tooltip', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The tooltip; defaults to the localized "Close".'), ApiParameter(name: 'enabled', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether the button responds to presses; when false it is shown\ndisabled and neither calls [onPressed] nor pops.')])], properties: [], methods: [], values: []),
  'Oito2ColorDisk': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A round color swatch that can be selected, as in accent color pickers.\n\nA ring in [color] itself surrounds the selected disk, and a fainter one\nshows while the pointer hovers it or the keyboard focus is on it. A\ndisk whose color has less than 3:1 contrast with the surface gets a\nthin outline, so it doesn\'t blend into the background.', signature: '', constructors: [ApiConstructor(name: 'Oito2ColorDisk', doc: 'Creates a color disk.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'color', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: 'The swatch color.'), ApiParameter(name: 'selected', type: 'bool', isRequired: true, isNamed: true, defaultValue: '', doc: 'Whether this color is the selected one.'), ApiParameter(name: 'onPressed', type: 'VoidCallback?', isRequired: true, isNamed: true, defaultValue: '', doc: 'Called when the disk is activated; null disables it.'), ApiParameter(name: 'label', type: 'String', isRequired: true, isNamed: true, defaultValue: '', doc: 'The color name for assistive technologies and the tooltip.'), ApiParameter(name: 'size', type: 'double', isRequired: false, isNamed: true, defaultValue: '20', doc: 'The disk diameter, without its ring.')])], properties: [], methods: [], values: []),
  'Oito2ColorFormat': ApiEntry(kind: 'enum', package: 'oito2_ui', doc: 'The text format of an [Oito2ColorPicker]\'s fields.', signature: '', constructors: [], properties: [], methods: [], values: [ApiMember(name: 'hex', signature: '', doc: 'One hexadecimal field, such as `#3584E4`.'), ApiMember(name: 'rgb', signature: '', doc: 'Red, green and blue fields from 0 to 255.'), ApiMember(name: 'hsl', signature: '', doc: 'Hue, saturation and lightness fields.')]),
  'Oito2ColorPicker': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A color picker: a saturation and brightness area, a hue slider, an\noptional opacity slider, text fields in a chosen [Oito2ColorFormat]\nand optional [swatches].\n\nEvery part works by pointer and by keyboard: the arrow keys move the\narea and the sliders by 1%, or 10% with Shift (on the sliders, only the\nreading-direction arrows take Shift), and the fields apply on Enter or\nwhen they lose focus. Use [Oito2ColorPickerButton] to show\nit in a popover.', signature: '', constructors: [ApiConstructor(name: 'Oito2ColorPicker', doc: 'Creates a color picker.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'value', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: 'The current color.'), ApiParameter(name: 'onChanged', type: 'ValueChanged<Color>', isRequired: true, isNamed: true, defaultValue: '', doc: 'Called with each new color.'), ApiParameter(name: 'showAlpha', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether the opacity slider shows and the hex field includes the\nalpha channel; without it, edits keep the current opacity.'), ApiParameter(name: 'swatches', type: 'List<Color>', isRequired: false, isNamed: true, defaultValue: 'const []', doc: 'Preset colors offered below the fields.'), ApiParameter(name: 'initialFormat', type: 'Oito2ColorFormat', isRequired: false, isNamed: true, defaultValue: 'Oito2ColorFormat.hex', doc: 'The field format shown first.'), ApiParameter(name: 'width', type: 'double', isRequired: false, isNamed: true, defaultValue: '264', doc: 'The picker width.')])], properties: [], methods: [], values: []),
  'Oito2ColorPickerButton': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A button showing a color swatch and its hex value that opens an\n[Oito2ColorPicker] in a popover.', signature: '', constructors: [ApiConstructor(name: 'Oito2ColorPickerButton', doc: 'Creates a color picker button.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'value', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: 'The current color.'), ApiParameter(name: 'onChanged', type: 'ValueChanged<Color>?', isRequired: true, isNamed: true, defaultValue: '', doc: 'Called with each new color; the button is disabled when null.'), ApiParameter(name: 'showAlpha', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether the picker offers opacity and the label includes the alpha\nchannel.'), ApiParameter(name: 'swatches', type: 'List<Color>', isRequired: false, isNamed: true, defaultValue: 'const []', doc: 'Preset colors offered in the picker.'), ApiParameter(name: 'semanticLabel', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The accessibility label of the button and the popover, such as what\nthe color is for.')])], properties: [], methods: [], values: []),
  'Oito2ColorRoles': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'The handful of role colors a color theme family defines, from which\n[Oito2ColorTheme.fromRoles] derives a complete oito2 scheme.\n\nThe roles follow the vocabulary most theme families publish: a page\n[background], a [card] surface, a [secondary] surface, a [border], the\ntext colors and the accents. Values are taken as given; contrast\nadjustments happen in [Oito2ColorTheme.fromRoles].', signature: '', constructors: [ApiConstructor(name: 'Oito2ColorRoles', doc: 'Creates the role colors of a scheme.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'brightness', type: 'Brightness', isRequired: true, isNamed: true, defaultValue: '', doc: 'Whether the scheme is light or dark.'), ApiParameter(name: 'background', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: 'The page background.'), ApiParameter(name: 'card', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: 'The main surface of cards, panes and fields.'), ApiParameter(name: 'foreground', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: 'The body text color.'), ApiParameter(name: 'primary', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: 'The signature accent, used as the primary fill.'), ApiParameter(name: 'secondary', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: 'A surface one step above [card], such as a selected row.'), ApiParameter(name: 'mutedForeground', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: 'Secondary text, such as captions and placeholders.'), ApiParameter(name: 'destructive', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: 'The color of errors and destructive actions.'), ApiParameter(name: 'border', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: 'Borders and dividers.'), ApiParameter(name: 'success', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: 'The color of success states.'), ApiParameter(name: 'warning', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: 'The color of warning states.'), ApiParameter(name: 'info', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: 'The color of informational states.'), ApiParameter(name: 'syntax', type: 'Oito2SyntaxPalette', isRequired: true, isNamed: true, defaultValue: '', doc: 'The syntax highlighting colors.')])], properties: [], methods: [], values: []),
  'Oito2ColorScheme': ApiEntry(kind: 'abstract class', package: 'oito2_ui', doc: 'Material [ColorScheme]s of the oito2 schemes.\n\nShortcuts to [Oito2ColorTheme.colorScheme]; use [Oito2ColorTheme] when\nthe semantic, chrome or syntax colors are needed too.', signature: '', constructors: [ApiConstructor(name: 'Oito2ColorScheme', doc: '', isConst: false, isFactory: false, parameters: [])], properties: [], methods: [ApiMember(name: 'light', signature: 'static light(Color? accent, bool highContrast) → ColorScheme', doc: 'The light oito2 base scheme with [accent] as the primary hue.'), ApiMember(name: 'dark', signature: 'static dark(Color? accent, bool highContrast) → ColorScheme', doc: 'The dark oito2 base scheme with [accent] as the primary hue.')], values: []),
  'Oito2ColorTheme': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'The complete, resolved colors of one oito2 scheme: the Material\n[colorScheme] plus the oito2 [semantic], [chrome] and [syntax] colors.\n\nBuild it with [Oito2ColorTheme.light] or [Oito2ColorTheme.dark] for the\noito2 base scheme, or with [Oito2ColorTheme.fromRoles] for any other\ncolor theme family, such as the presets of `oito2_ui_themes` or an\napp\'s own brand colors.\n\nText roles are guaranteed to reach WCAG AA: `onSurface`,\n`onSurfaceVariant` and every [semantic] and [syntax] color reach\n4.5:1 against every surface of the scheme and against [background], and\n`outline` reaches 3:1. With high contrast the targets rise to 7:1 and\n4.5:1.', signature: '', constructors: [ApiConstructor(name: 'Oito2ColorTheme', doc: 'Creates a color theme from resolved values.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'colorScheme', type: 'ColorScheme', isRequired: true, isNamed: true, defaultValue: '', doc: 'The Material color scheme.'), ApiParameter(name: 'background', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: 'The page background, used as the scaffold background.'), ApiParameter(name: 'semantic', type: 'Oito2SemanticColors', isRequired: true, isNamed: true, defaultValue: '', doc: 'Text-safe accent and status colors.'), ApiParameter(name: 'chrome', type: 'Oito2ChromeColors', isRequired: true, isNamed: true, defaultValue: '', doc: 'Structural chrome colors.'), ApiParameter(name: 'syntax', type: 'Oito2SyntaxPalette', isRequired: true, isNamed: true, defaultValue: '', doc: 'Syntax highlighting colors.'), ApiParameter(name: 'highContrast', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether this theme uses the high-contrast targets.')]), ApiConstructor(name: 'Oito2ColorTheme.light', doc: 'The light oito2 base scheme: GTK-style neutrals with [accent] as the\nprimary hue.\n\n[accent] defaults to [Oito2AccentColor.fallback]. The primary fill\nkeeps white text: its lightness is lowered only as far as needed for\nwhite to reach 4.5:1 (7:1 with [highContrast]).', isConst: false, isFactory: true, parameters: [ApiParameter(name: 'accent', type: 'Color?', isRequired: false, isNamed: true, defaultValue: '', doc: ''), ApiParameter(name: 'highContrast', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: '')]), ApiConstructor(name: 'Oito2ColorTheme.dark', doc: 'The dark oito2 base scheme: GTK-style neutrals with [accent] as the\nprimary hue.\n\nSee [Oito2ColorTheme.light] for how [accent] and [highContrast] apply.', isConst: false, isFactory: true, parameters: [ApiParameter(name: 'accent', type: 'Color?', isRequired: false, isNamed: true, defaultValue: '', doc: ''), ApiParameter(name: 'highContrast', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: '')]), ApiConstructor(name: 'Oito2ColorTheme.fromRoles', doc: 'A scheme derived from the role colors of a theme family.\n\nThe primary fill keeps [Oito2ColorRoles.primary] as given, with black\nor white text, whichever contrasts more. The surface ladder runs from\nthe lower of the background and the card up to the secondary surface:\n\n- `surfaceContainerLowest` is whichever of `background` and `card`\n  sits lower (darker in a dark scheme, lighter in a light one);\n- `surfaceContainerLow` is halfway from it to `card`;\n- `surfaceContainer` and `surfaceContainerHigh` are one third and two\n  thirds of the way from `card` to `secondary`, and\n  `surfaceContainerHighest` is `secondary`;\n- the title bar is `surfaceContainer`;\n- `outline` is `border` mixed 35% toward `foreground`, and\n  `outlineVariant` is `border`.\n\nText, outline, semantic and syntax colors are then adjusted to reach\nWCAG AA against every surface, as for the base scheme, or AAA with\n[highContrast].', isConst: false, isFactory: true, parameters: [ApiParameter(name: 'roles', type: 'Oito2ColorRoles', isRequired: true, isNamed: false, defaultValue: '', doc: ''), ApiParameter(name: 'highContrast', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: '')])], properties: [ApiMember(name: 'brightness', signature: 'Brightness', doc: 'The brightness of this theme.'), ApiMember(name: 'surfaces', signature: 'List<Color>', doc: 'Every surface of this theme: [background], the chrome surfaces and\nall `ColorScheme` surface roles.')], methods: [], values: []),
  'Oito2Command': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'An action the user can run by a keyboard shortcut or from the command\npalette.', signature: '', constructors: [ApiConstructor(name: 'Oito2Command', doc: 'Creates a command.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'id', type: 'String', isRequired: true, isNamed: true, defaultValue: '', doc: 'A unique identifier; an inner [Oito2Commands] scope overrides an\nouter command with the same id.'), ApiParameter(name: 'label', type: 'String', isRequired: true, isNamed: true, defaultValue: '', doc: 'The name shown in the command palette.'), ApiParameter(name: 'onInvoke', type: 'VoidCallback', isRequired: true, isNamed: true, defaultValue: '', doc: 'Called when the command runs, from its shortcut or the command\npalette.'), ApiParameter(name: 'shortcut', type: 'Oito2Shortcut?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The keyboard shortcut, if any.'), ApiParameter(name: 'description', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'A longer explanation shown in the command palette.'), ApiParameter(name: 'group', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The palette group, such as "Navigation" or "View".'), ApiParameter(name: 'icon', type: 'IconData?', isRequired: false, isNamed: true, defaultValue: '', doc: 'An icon shown in the command palette.'), ApiParameter(name: 'keywords', type: 'List<String>', isRequired: false, isNamed: true, defaultValue: 'const []', doc: 'Extra words the palette search matches.'), ApiParameter(name: 'enabled', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether the command can run now; disabled commands neither react to\ntheir shortcut nor appear in the command palette.')])], properties: [], methods: [], values: []),
  'Oito2Commands': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'Registers [commands] for the widgets below it: while keyboard focus is\ninside [child], their shortcuts run them, and the command palette lists\nthem.\n\nScopes nest: a shortcut first matches the commands of the innermost\nscope around the focus, then those of the enclosing scopes, and an\ninner command replaces an outer one with the same [Oito2Command.id].\nSequences such as `G H` wait up to [sequenceTimeout] between chords.\nShortcuts without Control, Alt, Command or the primary modifier (such\nas `G H` or `Shift+/`) don\'t run while a text field has focus, so they\ndon\'t steal typing.', signature: '', constructors: [ApiConstructor(name: 'Oito2Commands', doc: 'Creates a command scope.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'commands', type: 'List<Oito2Command>', isRequired: true, isNamed: true, defaultValue: '', doc: 'The commands of this scope.'), ApiParameter(name: 'child', type: 'Widget', isRequired: true, isNamed: true, defaultValue: '', doc: 'The widgets the commands apply to.'), ApiParameter(name: 'sequenceTimeout', type: 'Duration', isRequired: false, isNamed: true, defaultValue: 'const Duration(seconds: 1)', doc: 'The longest wait between the chords of a sequence.')])], properties: [], methods: [ApiMember(name: 'availableAt', signature: 'static availableAt(BuildContext context) → List<Oito2Command>', doc: 'Returns the enabled commands available at [context]: those of every\nenclosing scope, the innermost first, with inner commands replacing\nouter ones of the same id.'), ApiMember(name: 'conflicts', signature: 'static conflicts(List<Oito2Command> commands, TargetPlatform? platform) → List<(Oito2Command, Oito2Command)>', doc: 'Returns the pairs of [commands] whose shortcuts clash on [platform]\n(the current platform by default): the same shortcut, or one that is\na prefix of another (the longer one could never run).')], values: []),
  'Oito2ContextMenuRegion': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'Opens a menu of [menuChildren] over [child] on a secondary click, a\nlong press, Shift+F10 or the menu key.\n\nThe menu is a `MenuAnchor`, so [menuChildren] are `MenuItemButton`s,\n`SubmenuButton`s for nested menus, `Oito2CheckedMenuItem`s and\ndividers. It opens where the pointer is, or over the center of\n[child] from the keyboard, which needs the focus inside [child] and\nmoves it to the first item that can take it. On\nthe web, the browser\'s own menu is turned off while the pointer is\nover [child].', signature: '', constructors: [ApiConstructor(name: 'Oito2ContextMenuRegion', doc: 'Creates a context menu region.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'child', type: 'Widget', isRequired: true, isNamed: true, defaultValue: '', doc: 'The widget the menu belongs to.'), ApiParameter(name: 'menuChildren', type: 'List<Widget>', isRequired: true, isNamed: true, defaultValue: '', doc: 'The menu items.'), ApiParameter(name: 'enabled', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether the menu can open; when false, the browser\'s own menu stays\navailable on the web.'), ApiParameter(name: 'onOpen', type: 'VoidCallback?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called when the menu opens.'), ApiParameter(name: 'onClose', type: 'VoidCallback?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called when the menu closes.')])], properties: [], methods: [], values: []),
  'Oito2Contrast': ApiEntry(kind: 'abstract class', package: 'oito2_ui', doc: 'Color contrast helpers based on WCAG 2.2 relative luminance.', signature: '', constructors: [ApiConstructor(name: 'Oito2Contrast', doc: '', isConst: false, isFactory: false, parameters: [])], properties: [ApiMember(name: 'textAA', signature: 'static double', doc: 'Minimum contrast ratio for normal text at WCAG level AA.'), ApiMember(name: 'nonTextAA', signature: 'static double', doc: 'Minimum contrast ratio for large text and for user interface\ncomponents and graphics at WCAG level AA.'), ApiMember(name: 'textAAA', signature: 'static double', doc: 'Minimum contrast ratio for normal text at WCAG level AAA.')], methods: [ApiMember(name: 'ratio', signature: 'static ratio(Color a, Color b) → double', doc: 'Returns the WCAG contrast ratio between [a] and [b], from 1 (no\ncontrast) to 21 (black on white). The alpha channel is ignored.'), ApiMember(name: 'foregroundFor', signature: 'static foregroundFor(Color background) → Color', doc: 'Returns black or white, whichever has the higher contrast ratio\nagainst [background].'), ApiMember(name: 'minRatio', signature: 'static minRatio(Color color, Iterable<Color> backgrounds) → double', doc: 'Returns the lowest contrast ratio between [color] and any of\n[backgrounds], or 21 when [backgrounds] is empty.'), ApiMember(name: 'ensure', signature: 'static ensure(Color color, Iterable<Color> backgrounds, double target) → Color', doc: 'Returns the color closest to [color] that reaches [target] contrast\nagainst every color in [backgrounds].\n\nKeeps hue, saturation and alpha and moves only the HSL lightness,\nsearching in steps of 0.005, darker before lighter at each distance,\nand returning the first lightness that satisfies [target]. Returns\n[color] unchanged when it already satisfies [target] or when\n[backgrounds] is empty. When no lightness satisfies it, returns black\nor white, whichever reaches the higher minimum ratio.')], values: []),
  'Oito2ControlAffinity': ApiEntry(kind: 'enum', package: 'oito2_ui', doc: 'Where the control of a toggle list tile sits.', signature: '', constructors: [], properties: [], methods: [], values: [ApiMember(name: 'leading', signature: '', doc: 'Before the title.'), ApiMember(name: 'trailing', signature: '', doc: 'After the title.'), ApiMember(name: 'platform', signature: '', doc: 'The usual side of the control: leading for check boxes and radios,\ntrailing for switches.')]),
  'Oito2CopyButton': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'An icon button that copies [text] to the clipboard.\n\nAfter a copy the icon turns into a check mark and the tooltip into\n"Copied" for [feedbackDuration], and assistive technologies hear the\nchange. When the platform refuses the copy, such as a browser without\nclipboard permission, the button shows a cross and "Couldn\'t copy"\ninstead, and [onError] receives the error.', signature: '', constructors: [ApiConstructor(name: 'Oito2CopyButton', doc: 'Creates a copy button.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'text', type: 'String', isRequired: true, isNamed: true, defaultValue: '', doc: 'The text copied.'), ApiParameter(name: 'tooltip', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The tooltip before copying; defaults to the localized "Copy".'), ApiParameter(name: 'onCopied', type: 'VoidCallback?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called after each copy.'), ApiParameter(name: 'onError', type: 'ValueChanged<Object>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with the error when the platform refuses a copy.'), ApiParameter(name: 'feedbackDuration', type: 'Duration', isRequired: false, isNamed: true, defaultValue: 'const Duration(milliseconds: 1500)', doc: 'How long the check mark and the "Copied" tooltip, or the failure,\nshow.')])], properties: [], methods: [], values: []),
  'Oito2CopyField': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A read-only field showing [value], such as a link or a token, with an\n[Oito2CopyButton] at its end.', signature: '', constructors: [ApiConstructor(name: 'Oito2CopyField', doc: 'Creates a copy field.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'value', type: 'String', isRequired: true, isNamed: true, defaultValue: '', doc: 'The text shown and copied.'), ApiParameter(name: 'labelText', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The field label.'), ApiParameter(name: 'obscure', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether the value shows as dots, such as for a secret.'), ApiParameter(name: 'onCopied', type: 'VoidCallback?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called after each copy.'), ApiParameter(name: 'onError', type: 'ValueChanged<Object>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with the error when the platform refuses a copy.')])], properties: [], methods: [], values: []),
  'Oito2DateEntry': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A date text field that accepts the locale\'s compact date format (such\nas mm/dd/yyyy) and offers a calendar picker button.\n\nParsing, the format hint and the error messages come from\n`MaterialLocalizations`, so they follow the app language. Errors show\nafter the field loses focus or is submitted.', signature: '', constructors: [ApiConstructor(name: 'Oito2DateEntry', doc: 'Creates a date entry.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'firstDate', type: 'DateTime', isRequired: true, isNamed: true, defaultValue: '', doc: 'The earliest accepted date.'), ApiParameter(name: 'lastDate', type: 'DateTime', isRequired: true, isNamed: true, defaultValue: '', doc: 'The latest accepted date.'), ApiParameter(name: 'initialDate', type: 'DateTime?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The date shown at start.'), ApiParameter(name: 'onChanged', type: 'ValueChanged<DateTime?>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with each valid date, or null when the field is emptied.\n\nInvalid text doesn\'t call it, so the last valid date stays reported;\n[onErrorChanged] tells when the text doesn\'t parse.'), ApiParameter(name: 'onErrorChanged', type: 'ValueChanged<String?>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with the error message when the text stops being a valid\ndate, and with null when it is valid again.'), ApiParameter(name: 'selectableDayPredicate', type: 'SelectableDayPredicate?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Decides which days between [firstDate] and [lastDate] are accepted;\nevery day is when null.'), ApiParameter(name: 'labelText', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The field label; defaults to the localized "Enter Date".'), ApiParameter(name: 'acceptEmpty', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether an empty field is valid.'), ApiParameter(name: 'autofocus', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether the field takes focus when shown.'), ApiParameter(name: 'focusNode', type: 'FocusNode?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The focus node; one is created when null.'), ApiParameter(name: 'showPickerButton', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether the calendar picker button is shown.'), ApiParameter(name: 'currentDate', type: 'DateTime?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The day the calendar marks as today and opens on when no date is\nset; the current date by default.')])], properties: [], methods: [], values: []),
  'Oito2DatePicker': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A field-like button that shows a date, or a date range when\n[onRangeChanged] is set, and opens an [Oito2Calendar] in a popover to\nchange it.\n\nEnter, Space or Alt+Down opens the calendar, which takes the focus; a\npick closes it. The field is disabled when neither [onChanged] nor\n[onRangeChanged] is set.', signature: '', constructors: [ApiConstructor(name: 'Oito2DatePicker', doc: 'Creates a date picker.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'firstDate', type: 'DateTime', isRequired: true, isNamed: true, defaultValue: '', doc: 'The earliest date that can be picked.'), ApiParameter(name: 'lastDate', type: 'DateTime', isRequired: true, isNamed: true, defaultValue: '', doc: 'The latest date that can be picked.'), ApiParameter(name: 'value', type: 'DateTime?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The picked date, in single mode.'), ApiParameter(name: 'onChanged', type: 'ValueChanged<DateTime>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with a picked date, in single mode.'), ApiParameter(name: 'range', type: 'DateTimeRange<DateTime>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The picked range, in range mode.'), ApiParameter(name: 'onRangeChanged', type: 'ValueChanged<DateTimeRange<DateTime>>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with a picked range; setting it turns on range mode.'), ApiParameter(name: 'labelText', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The field label.'), ApiParameter(name: 'hintText', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The text shown when nothing is picked; defaults to the localized\ndate format hint.'), ApiParameter(name: 'selectableDayPredicate', type: 'SelectableDayPredicate?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Decides which days between [firstDate] and [last