  'Oito2DateTimeEntry': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A date entry and a time entry side by side that report one combined\n[DateTime]. An empty time means midnight.', signature: '', constructors: [ApiConstructor(name: 'Oito2DateTimeEntry', doc: 'Creates a date and time entry.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'firstDate', type: 'DateTime', isRequired: true, isNamed: true, defaultValue: '', doc: 'The earliest accepted date.'), ApiParameter(name: 'lastDate', type: 'DateTime', isRequired: true, isNamed: true, defaultValue: '', doc: 'The latest accepted date.'), ApiParameter(name: 'initialDateTime', type: 'DateTime?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The date and time shown at start.'), ApiParameter(name: 'onChanged', type: 'ValueChanged<DateTime?>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with each new valid combination, or null without a date.\n\nIt isn\'t called while either field holds invalid text; once both\nparse again, it reports the combination if it changed.\n[onErrorChanged] tells when one of them doesn\'t parse.'), ApiParameter(name: 'onErrorChanged', type: 'ValueChanged<String?>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with the error message of the date field, or else of the time\nfield, when either stops parsing, and with null when both parse.'), ApiParameter(name: 'dateLabelText', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The date field label; defaults to the localized "Enter Date".'), ApiParameter(name: 'timeLabelText', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The time field label; defaults to the localized "Enter time".')])], properties: [], methods: [], values: []),
  'Oito2DesktopEnvironment': ApiEntry(kind: 'enum', package: 'oito2_ui', doc: 'A Linux desktop environment.', signature: '', constructors: [], properties: [], methods: [ApiMember(name: 'detect', signature: 'static detect(String? xdgCurrentDesktop, String? desktopSession) → Oito2DesktopEnvironment', doc: 'Detects the desktop environment from the values of the\n`XDG_CURRENT_DESKTOP` and `DESKTOP_SESSION` environment variables.\n\n`XDG_CURRENT_DESKTOP` is a colon-separated list (for example\n`Budgie:GNOME` or `ubuntu:GNOME`); its entries are checked in order and\nthe first recognized one wins. `DESKTOP_SESSION` is checked only when no\nentry is recognized. Matching ignores case. Returns [unknown] when\nneither value is recognized.')], values: [ApiMember(name: 'gnome', signature: '', doc: 'GNOME, including Ubuntu\'s and Pop!_OS\'s GNOME sessions.'), ApiMember(name: 'kde', signature: '', doc: 'KDE Plasma.'), ApiMember(name: 'xfce', signature: '', doc: 'Xfce.'), ApiMember(name: 'budgie', signature: '', doc: 'Budgie.'), ApiMember(name: 'cosmic', signature: '', doc: 'COSMIC.'), ApiMember(name: 'cinnamon', signature: '', doc: 'Cinnamon.'), ApiMember(name: 'mate', signature: '', doc: 'MATE.'), ApiMember(name: 'lxqt', signature: '', doc: 'LXQt.'), ApiMember(name: 'pantheon', signature: '', doc: 'Pantheon (elementary OS).'), ApiMember(name: 'unity', signature: '', doc: 'Unity.'), ApiMember(name: 'unknown', signature: '', doc: 'A desktop environment not recognized by [detect].')]),
