  'Oito2DialogTitleBar': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'The title bar of a dialog: a title and a close button that pops the\ndialog route.\n\nThe close button follows the system window control style, falling back\nto the GNOME style where the platform has none (web, touch and macOS),\nand the side of the close button in the system button layout.', signature: '', constructors: [ApiConstructor(name: 'Oito2DialogTitleBar', doc: 'Creates a dialog title bar.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'title', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The dialog title, usually a [Text].'), ApiParameter(name: 'leading', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'A widget before the title, such as an [Icon] or an animated\n`Oito2AnimatedIcon` that tells what the dialog is about.'), ApiParameter(name: 'onClose', type: 'VoidCallback?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called when the close button is pressed; defaults to popping the\ncurrent route.'), ApiParameter(name: 'labels', type: 'Oito2WindowControlLabels?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Override of the close button\'s accessibility label, which otherwise\ncomes from [Oito2Localizations].')])], properties: [], methods: [], values: []),
  'Oito2Draggable': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A widget the user can move inside a [Stack], with the pointer or, once\nfocused, with the arrow keys.\n\nIt must be a direct child of a [Stack]. The position is relative to\nthe stack\'s top-left corner.', signature: '', constructors: [ApiConstructor(name: 'Oito2Draggable', doc: 'Creates a draggable widget.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'child', type: 'Widget', isRequired: true, isNamed: true, defaultValue: '', doc: 'The content that moves.'), ApiParameter(name: 'initialPosition', type: 'Offset', isRequired: false, isNamed: true, defaultValue: 'Offset.zero', doc: 'The initial offset from the stack\'s top-left corner; later changes\nare ignored.'), ApiParameter(name: 'onDragStart', type: 'VoidCallback?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called when a pointer drag starts.'), ApiParameter(name: 'onDragEnd', type: 'VoidCallback?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called when a pointer drag ends.'), ApiParameter(name: 'onMoved', type: 'ValueChanged<Offset>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with each new position, after a pointer or keyboard move.'), ApiParameter(name: 'keyboardStep', type: 'double', isRequired: false, isNamed: true, defaultValue: '8', doc: 'How far one arrow key press, or one accessibility move action, moves\nthe widget, in logical pixels.'), ApiParameter(name: 'semanticLabel', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The name assistive technologies read for the widget, which they also\ntell can be moved with the arrow keys or the move actions.')])], properties: [], methods: [], values: []),
  'Oito2EdgeFocusInterceptor': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'Keeps arrow-key focus navigation inside [child]: at the edges of the\ngroup the arrow keys stop instead of moving focus out of it.\n\nUseful for grids and toolbars navigated with the arrow keys, so the\nkeyboard user doesn\'t fall out of the group by accident. Tab and\nShift+Tab still move to the widgets around the group.', signature: '', constructors: [ApiConstructor(name: 'Oito2EdgeFocusInterceptor', doc: 'Creates an edge focus interceptor.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'child', type: 'Widget', isRequired: true, isNamed: true, defaultValue: '', doc: 'The group of focusable widgets.')])], properties: [], methods: [], values: []),
  'Oito2EditableLabel': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A text label that turns into a field to rename it in place.\n\nA double click, Enter or F2 starts editing with the text selected.\nEnter or leaving the field keeps the change, calling [onSubmitted]\nwith the trimmed text when it changed and isn\'t empty; Escape\nrestores the text. [onSubmitted] null makes the label read-only.', signature: '', constructors: [ApiConstructor(name: 'Oito2EditableLabel', doc: 'Creates an editable label.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'text', type: 'String', isRequired: true, isNamed: true, defaultValue: '', doc: 'The label text.'), ApiParameter(name: 'onSubmitted', type: 'ValueChanged<String>?', isRequired: true, isNamed: true, defaultValue: '', doc: 'Called with the new, trimmed text after a change; null makes the\nlabel read-only.'), ApiParameter(name: 'style', type: 'TextStyle?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The text style; defaults to `bodyLarge`.'), ApiParameter(name: 'placeholder', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The text shown in the placeholder color while [text] is empty.'), ApiParameter(name: 'focusNode', type: 'FocusNode?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The focus node of the label; one is created when null.')])], properties: [], methods: [], values: []),
  'Oito2EntrySegment': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'One part of an [Oito2SegmentedEntry].', signature: '', constructors: [ApiConstructor(name: 'Oito2EntrySegment', doc: 'Creates a segment that holds up to [length] characters.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'length', type: 'int', isRequired: true, isNamed: true, defaultValue: '', doc: 'The number of characters the segment holds.'), ApiParameter(name: 'hint', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The placeholder, such as `000`.'), ApiParameter(name: 'numeric', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether only digits are accepted.'), ApiParameter(name: 'label', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The accessibility label; defaults to the [Oito2Localizations]\n"part n of m" string.')])], properties: [], methods: [], values: []),
  'Oito2ExpandButtonPosition': ApiEntry(kind: 'enum', package: 'oito2_ui', doc: 'Where [Oito2Expandable] places its expand button.', signature: '', constructors: [], properties: [], methods: [], values: [ApiMember(name: 'start', signature: '', doc: 'Before the header.'), ApiMember(name: 'end', signature: '', doc: 'After the header.')]),
  'Oito2Expandable': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A header that shows or hides [child] when activated.\n\nThe whole header row toggles the content, with keyboard support and the\nexpanded state exposed to assistive technologies.\n\nWith [onChanged], the state is controlled: activating the header only\ncalls [onChanged], and the content follows [isExpanded], so the parent\ndecides whether it changes. Without [onChanged], [isExpanded] is only\nthe initial state and the header toggles the content itself.', signature: '', constructors: [ApiConstructor(name: 'Oito2Expandable', doc: 'Creates an expandable section.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'header', type: 'Widget', isRequired: true, isNamed: true, defaultValue: '', doc: 'The always-visible header, usually a [Text].'), ApiParameter(name: 'child', type: 'Widget', isRequired: true, isNamed: true, defaultValue: '', doc: 'The content shown when expanded.'), ApiParameter(name: 'collapsedChild', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The content shown when collapsed, such as a summary.'), ApiParameter(name: 'isExpanded', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether the content is shown; only the initial state when\n[onChanged] is null.'), ApiParameter(name: 'onChanged', type: 'ValueChanged<bool>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with the requested state when the header is activated; when\nset, the parent applies it through [isExpanded].'), ApiParameter(name: 'buttonPosition', type: 'Oito2ExpandButtonPosition', isRequired: false, isNamed: true, defaultValue: 'Oito2ExpandButtonPosition.end', doc: 'Where the expand button sits.'), ApiParameter(name: 'gap', type: 'double', isRequired: false, isNamed: true, defaultValue: 'Oito2Spacing.xs', doc: 'Space between the header and the content.')])], properties: [], methods: [], values: []),
  'Oito2ExpansionPanel': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A bordered stack of sections, each with a header that expands its\ncontent, as an accordion.\n\n[headers] and [children] pair up by index. With [collapseOnExpand],\nopening a section closes the others, so at most one is open.\n[onExpansionChanged] reports each section that opens or closes.', signature: '', constructors: [ApiConstructor(name: 'Oito2ExpansionPanel', doc: 'Creates an expansion panel.\n\nThrows an [AssertionError] in debug builds, when built, if [headers]\nand [children] differ in length.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'headers', type: 'List<Widget>', isRequired: true, isNamed: true, defaultValue: '', doc: 'The section headers, usually [Text]s.'), ApiParameter(name: 'children', type: 'List<Widget>', isRequired: true, isNamed: true, defaultValue: '', doc: 'The section contents, in the order of [headers]; one per header.'), ApiParameter(name: 'initiallyExpanded', type: 'Set<int>', isRequired: false, isNamed: true, defaultValue: 'const {}', doc: 'The indexes of the sections open at start; with [collapseOnExpand],\nonly the first of them opens.'), ApiParameter(name: 'collapseOnExpand', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether opening a section closes the others.'), ApiParameter(name: 'placeDividers', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether dividers separate the sections.'), ApiParameter(name: 'padding', type: 'EdgeInsetsGeometry', isRequired: false, isNamed: true, defaultValue: 'const EdgeInsets.symmetric(horizontal: Oito2Spacing.md, vertical: Oito2Spacing.sm)', doc: 'Space around each section.'), ApiParameter(name: 'onExpansionChanged', type: 'void Function(int, bool)?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with the index of each section that opens or closes and\nwhether it is now open, including the sections [collapseOnExpand]\ncloses, which are reported before the section that opened.')])], properties: [], methods: [], values: []),
  'Oito2FloatingPanel': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A non-modal window inside the app, such as an inspector or a tool\npalette, that the user moves, resizes, minimizes and maximizes.\n\nPlace it in a [Stack]; it covers the stack to know its bounds but only\ntakes pointer events on itself. Dragging the title bar moves it and a\ndouble click maximizes or restores it; with [resizable] its right and\nbottom edges and corner resize it. Minimizing leaves only the title\nbar. With the focus on the title bar the arrow keys move the panel and\nShift with the arrows resizes it. The title bar keeps inside the\nstack. Minimized content keeps its state.\n\nPanels in the same [Stack] keep the stacking order of its children:\nclicking a panel doesn\'t bring it to the front, so the app reorders\nthe children when it wants that.', signature: '', constructors: [ApiConstructor(name: 'Oito2FloatingPanel', doc: 'Creates a floating panel.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'title', type: 'String', isRequired: true, isNamed: true, defaultValue: '', doc: 'The panel title.'), ApiParameter(name: 'child', type: 'Widget', isRequired: true, isNamed: true, defaultValue: '', doc: 'The panel content.'), ApiParameter(name: 'initialRect', type: 'Rect', isRequired: false, isNamed: true, defaultValue: 'const Rect.fromLTWH(40, 40, 360, 280)', doc: 'The position and size at start, in the stack\'s coordinates.'), ApiParameter(name: 'minSize', type: 'Size', isRequired: false, isNamed: true, defaultValue: 'const Size(220, 140)', doc: 'The smallest size the panel can be resized to.'), ApiParameter(name: 'resizable', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether the edges resize the panel.'), ApiParameter(name: 'onClose', type: 'VoidCallback?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called by the close button; the panel shows no close button when\nnull.'), ApiParameter(name: 'onRectChanged', type: 'ValueChanged<Rect>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with the new rectangle on every move or resize step,\nincluding each step of a drag.'), ApiParameter(name: 'controlStyle', type: 'Oito2WindowControlStyle', isRequired: false, isNamed: true, defaultValue: 'Oito2WindowControlStyle.gnome', doc: 'The look of the title bar buttons.'), ApiParameter(name: 'keyboardStep', type: 'double', isRequired: false, isNamed: true, defaultValue: '16', doc: 'The distance, in logical pixels, one arrow key press moves or\nresizes the panel.')])], properties: [], methods: [], values: []),
  'Oito2FocusBorder': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'Draws a 2-pixel ring in the text-safe primary tone around [child]\nwhile a widget inside it has keyboard focus.\n\nThe ring shows only in keyboard navigation mode, not after pointer\nclicks, and doesn\'t affect layout.', signature: '', constructors: [ApiConstructor(name: 'Oito2FocusBorder', doc: 'Creates a focus border.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'child', type: 'Widget', isRequired: true, isNamed: true, defaultValue: '', doc: 'The content the ring surrounds.'), ApiParameter(name: 'borderRadius', type: 'BorderRadius', isRequired: false, isNamed: true, defaultValue: 'Oito2Radius.mediumAll', doc: 'The ring corner radius.'), ApiParameter(name: 'focused', type: 'bool?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Forces the ring on or off; null follows keyboard focus and the\nhighlight mode.')])], properties: [], methods: [], values: []),
  'Oito2Format': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'Locale-aware formatting of byte sizes, compact numbers and relative\ntimes, such as "1.5 MB", "1.23K" and "3 minutes ago".\n\nNumbers follow the [locale] through `intl`; relative times use the\n[strings] of [Oito2Localizations]. [Oito2Format.of] takes both from a\nwidget context. Plain numbers, dates and times are formatted with\n`intl` directly.', signature: '', constructors: [ApiConstructor(name: 'Oito2Format', doc: 'Creates a formatter for [locale], such as `en` or `pt_BR`, with the\nrelative-time [strings]; locales `intl` doesn\'t know fall back to\nEnglish number formats.', isConst: false, isFactory: false, parameters: [ApiParameter(name: 'locale', type: 'String', isRequired: false, isNamed: true, defaultValue: '\'en\'', doc: ''), ApiParameter(name: 'strings', type: 'Oito2Localizations', isRequired: false, isNamed: true, defaultValue: 'const Oito2LocalizationsEn()', doc: 'The relative-time strings.')]), ApiConstructor(name: 'Oito2Format.of', doc: 'Creates a formatter for the locale and the [Oito2Localizations] of\n[context], with English when [context] has no locale.', isConst: false, isFactory: true, parameters: [ApiParameter(name: 'context', type: 'BuildContext', isRequired: true, isNamed: false, defaultValue: '', doc: '')])], properties: [], methods: [ApiMember(name: 'bytes', signature: 'bytes(int bytes, Oito2ByteUnits units, int fractionDigits) → String', doc: 'Formats a byte count in [units], such as `1536` as "1.5 kB" (or\n"1,5 kB" in Portuguese), with at most [fractionDigits] decimals.\n\nPicks the largest unit, up to petabytes, that keeps the value at\nleast 1; counts below one kilobyte keep no decimals. Negative counts\nkeep their sign.'), ApiMember(name: 'compactNumber', signature: 'compactNumber(num value) → String', doc: 'Formats [value] in compact form with three significant digits, such\nas `1234` as "1.23K" (or "1,23 mil" in Portuguese).'), ApiMember(name: 'relativeTime', signature: 'relativeTime(DateTime time, DateTime? now) → String', doc: 'Describes [time] relative to [now] (the current time by default),\nsuch as "3 minutes ago" or "in 2 days", with [strings].\n\nTimes within 45 seconds read as [Oito2Localizations.justNow]. Larger\ndifferences are rounded to minutes below 45 minutes, hours below 22\nhours, days below six and a half days, weeks below 30 days, months\n(of 30 days) below 365 days and years beyond.')], values: []),
  'Oito2FreedesktopIcons': ApiEntry(kind: 'enum', package: 'oito2_ui', doc: 'Icons named after the freedesktop.org Icon Naming Specification, drawn\nwith the Lucide icons oito2_ui uses.\n\nLinux integrations refer to icons by these names, for example in\n`.desktop` files, notifications and tray items; [byName] turns such a\nname into an icon. Each value keeps its specification name in\n[iconName], such as `document-open`.\n\n```dart\nIcon(Oito2FreedesktopIcons.documentOpen.icon);\nIcon(Oito2FreedesktopIcons.byName(\'dialog-warning\')?.icon);\n```', signature: '', constructors: [], properties: [], methods: [ApiMember(name: 'byName', signature: 'static byName(String name) → Oito2FreedesktopIcons?', doc: 'Returns the icon for a specification [name], such as\n`document-save`, or null when nothing matches.\n\nTrailing `-symbolic`, `-rtl` and `-ltr` suffixes are ignored, and a\nname without a mapping falls back, as the specification does, to the\nname without its last dash-separated part: `folder-documents` to\n`folder`.')], values: [ApiMember(name: 'addressBookNew', signature: '', doc: '`address-book-new`.'), ApiMember(name: 'applicationExit', signature: '', doc: '`application-exit`.'), ApiMember(name: 'appointmentNew', signature: '', doc: '`appointment-new`.'), ApiMember(name: 'callStart', signature: '', doc: '`call-start`.'), ApiMember(name: 'callStop', signature: '', doc: '`call-stop`.'), ApiMember(name: 'contactNew', signature: '', doc: '`contact-new`.'), ApiMember(name: 'documentNew', signature: '', doc: '`document-new`.'), ApiMember(name: 'documentOpen', signature: '', doc: '`document-open`.'), ApiMember(name: 'documentOpenRecent', signature: '', doc: '`document-open-recent`.'), ApiMember(name: 'documentPageSetup', signature: '', doc: '`document-page-setup`.'), ApiMember(name: 'documentPrint', signature: '', doc: '`document-print`.'), ApiMember(name: 'documentPrintPreview', signature: '', doc: '`document-print-preview`.'), ApiMember(name: 'documentProperties', sign