  'Oito2HeaderBar': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A header bar: the window title bar with the app\'s controls in it, as in\nGNOME apps.\n\n[start] widgets sit after the leading window buttons, such as a back\nbutton or a sidebar toggle, and [end] widgets before the trailing ones,\nsuch as icon buttons or menus. The middle shows [title], or [tabs] as\nan [Oito2TabBar] that switches the pages of a `TabBarView`.\n\nWith [search], a search button joins the end widgets; while the search\nis active the middle shows a search field in place of the title or the\ntabs, and Escape on the empty field, or the button again, closes it.\n[searchActive] makes the search controlled, together with\n[onSearchActiveChanged]; without it the bar keeps the state itself.\nWith [menuChildren], a menu button opens the app\'s main menu at the\nvery end.\n\nThe bar is an [Oito2WindowTitleBar], so it moves, maximizes and shows\nthe window controls as the system does.', signature: '', constructors: [ApiConstructor(name: 'Oito2HeaderBar', doc: 'Creates a header bar.\n\nThrows an [AssertionError] in debug builds when both [title] and\n[tabs] are given.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'title', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The title in the middle, usually a [Text].'), ApiParameter(name: 'tabs', type: 'List<Widget>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The tabs in the middle, usually [Oito2Tab]s, in place of [title].'), ApiParameter(name: 'tabController', type: 'TabController?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The controller of [tabs]; defaults to the closest\n`DefaultTabController`.'), ApiParameter(name: 'onTabTap', type: 'ValueChanged<int>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with the index of a tapped tab.'), ApiParameter(name: 'tabStyle', type: 'Oito2TabBarStyle', isRequired: false, isNamed: true, defaultValue: 'Oito2TabBarStyle.pill', doc: 'The look of [tabs].'), ApiParameter(name: 'tabWidth', type: 'double', isRequired: false, isNamed: true, defaultValue: '120', doc: 'The width of each tab of the pill style, in logical pixels; the tabs\nshare it equally and stay centered in the bar.'), ApiParameter(name: 'start', type: 'List<Widget>', isRequired: false, isNamed: true, defaultValue: 'const []', doc: 'The widgets after the leading window buttons.'), ApiParameter(name: 'end', type: 'List<Widget>', isRequired: false, isNamed: true, defaultValue: 'const []', doc: 'The widgets before the search and menu buttons and the trailing\nwindow buttons.'), ApiParameter(name: 'search', type: 'Oito2HeaderBarSearch?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The search; null shows no search button.'), ApiParameter(name: 'searchActive', type: 'bool?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Whether the search is open; null lets the bar keep that state.'), ApiParameter(name: 'onSearchActiveChanged', type: 'ValueChanged<bool>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with the requested search state when the search button,\nEscape or the field change it.'), ApiParameter(name: 'menuChildren', type: 'List<Widget>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The entries of the main menu, such as `MenuItemButton`s; null shows\nno menu button.'), ApiParameter(name: 'menuTooltip', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The tooltip of the menu button; defaults to the localized\n"Main menu".'), ApiParameter(name: 'controller', type: 'Oito2WindowController?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The window controller; defaults to the closest window scope\'s.'), ApiParameter(name: 'platform', type: 'Oito2Platform?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The platform used to compute [preferredSize]; see\n[Oito2WindowTitleBar.platform].'), ApiParameter(name: 'buttonSides', type: 'Oito2WindowButtonSides', isRequired: false, isNamed: true, defaultValue: 'Oito2WindowButtonSides.both', doc: 'Which sides of the system button layout the bar shows.'), ApiParameter(name: 'backgroundColor', type: 'Color?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The bar color; defaults to the title bar color of the theme.'), ApiParameter(name: 'border', type: 'BorderSide?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The line under the bar; defaults to the title bar theme\'s.')])], properties: [], methods: [], values: []),
  'Oito2HeaderBarSearch': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'The search of an [Oito2HeaderBar]: what the search field reports and\nhow it looks.', signature: '', constructors: [ApiConstructor(name: 'Oito2HeaderBarSearch', doc: 'Creates a header bar search.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'onChanged', type: 'ValueChanged<String>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called whenever the search text changes.'), ApiParameter(name: 'onSubmitted', type: 'ValueChanged<String>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called when the search text is submitted with Enter.'), ApiParameter(name: 'controller', type: 'TextEditingController?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Controls the search text, so it survives closing the search; one is\ncreated by the field when null.'), ApiParameter(name: 'hintText', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The hint of the search field; defaults to the localized "Search".'), ApiParameter(name: 'fieldWidth', type: 'double', isRequired: false, isNamed: true, defaultValue: '280', doc: 'The width of the search field, in logical pixels.')])], properties: [], methods: [], values: []),
  'Oito2HighlightedText': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'Text with the matches of a search query emphasized, such as search\nresults that show why each item matched.\n\nEach word of [query] and of [queries] is matched separately, ignoring\ncase and accents ("acao" matches "Ação"); overlapping matches merge.\n[splitWords], [ignoreCase], [wholeWords] and [matchAll] change how terms\nmatch. Matches use [highlightStyle], which defaults to bold text in the\ntext-safe primary tone.', signature: '', constructors: [ApiConstructor(name: 'Oito2HighlightedText', doc: 'Creates highlighted text.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'text', type: 'String', isRequired: true, isNamed: false, defaultValue: '', doc: 'The full text.'), ApiParameter(name: 'query', type: 'String', isRequired: true, isNamed: true, defaultValue: '', doc: 'The search query; its words are highlighted.'), ApiParameter(name: 'queries', type: 'List<String>', isRequired: false, isNamed: true, defaultValue: 'const []', doc: 'More queries highlighted along with [query].'), ApiParameter(name: 'splitWords', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether each word of a query matches on its own; when false, each\nquery matches as a whole phrase.'), ApiParameter(name: 'ignoreCase', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether matching ignores case and accents; when false, matches must\nhave the same case and accents.'), ApiParameter(name: 'wholeWords', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether a term matches only whole words, not the start, middle or end\nof a longer word.'), ApiParameter(name: 'matchAll', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether every occurrence of a term is highlighted; when false, only\nits first occurrence.'), ApiParameter(name: 'style', type: 'TextStyle?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The style of the text; defaults to the ambient text style.'), ApiParameter(name: 'highlightStyle', type: 'TextStyle?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The style merged into the matches; defaults to bold text in the\ntext-safe primary tone.'), ApiParameter(name: 'maxLines', type: 'int?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The maximum number of lines.'), ApiParameter(name: 'overflow', type: 'TextOverflow?', isRequired: false, isNamed: true, defaultValue: '', doc: 'How overflowing text is shown.'), ApiParameter(name: 'textAlign', type: 'TextAlign?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The horizontal alignment.')])], properties: [], methods: [ApiMember(name: 'matches', signature: 'static matches(String text, String query, List<String> queries, bool splitWords, bool ignoreCase, bool wholeWords, bool matchAll) → List<TextRange>', doc: 'Returns the ranges of [text] that match [query] and [queries], sorted\nand merged where they overlap or touch. The options work as on the\nwidget: by default each word matches everywhere, ignoring case and\naccents.')], values: []),
  'Oito2HoverCard': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A card of extra detail that opens over [child] while the pointer\nrests on it or the keyboard focus is inside it, such as a profile\npreview on a user name.\n\nThe card opens after [openDelay] and closes [closeDelay] after the\npointer leaves both the child and the card, or the focus leaves the\nchild. A long press opens it on touch screens; Escape and a tap\noutside close it. The card doesn\'t take the focus, so its content\nmust only repeat or preview what the child leads to.', signature: '', constructors: [ApiConstructor(name: 'Oito2HoverCard', doc: 'Creates a hover card.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'child', type: 'Widget', isRequired: true, isNamed: true, defaultValue: '', doc: 'The widget that opens the card.'), ApiParameter(name: 'cardBuilder', type: 'WidgetBuilder', isRequired: true, isNamed: true, defaultValue: '', doc: 'Builds the card content.'), ApiParameter(name: 'openDelay', type: 'Duration', isRequired: false, isNamed: true, defaultValue: 'const Duration(milliseconds: 500)', doc: 'The wait before the card opens after the pointer enters the child\nor the focus moves inside it.'), ApiParameter(name: 'closeDelay', type: 'Duration', isRequired: false, isNamed: true, defaultValue: 'const Duration(milliseconds: 300)', doc: 'The wait before the card closes after the pointer or the focus\nleaves.'), ApiParameter(name: 'placement', type: 'Oito2PopoverPlacement', isRequired: false, isNamed: true, defaultValue: 'Oito2PopoverPlacement.bottom', doc: 'The preferred side of the child.'), ApiParameter(name: 'alignment', type: 'Oito2PopoverAlignment', isRequired: false, isNamed: true, defaultValue: 'Oito2PopoverAlignment.center', doc: 'The alignment along the child\'s edge.'), ApiParameter(name: 'showArrow', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether the card points at the child with an arrow.'), ApiParameter(name: 'maxWidth', type: 'double', isRequired: false, isNamed: true, defaultValue: '320', doc: 'The largest card width.')])], properties: [], methods: [], values: []),
  'Oito2IconButton': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A square icon button sized by the oito2 icon button theme to the\ncontrol height: 34 pixels on pointer platforms and 40 on touch\nplatforms, where the tap target is padded to 48.\n\nWith [isSelected], it is a toggle: the selected state fills the button\nwith the secondary container and shows [selectedIcon] when given, and\nassistive technologies read its selected state. The focus ring shows\nin keyboard navigation.', signature: '', constructors: [ApiConstructor(name: 'Oito2IconButton', doc: 'Creates an icon button.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'icon', type: 'Widget', isRequired: true, isNamed: true, defaultValue: '', doc: 'The icon, usually an [Icon]; shown while not selected when\n[selectedIcon] is given.'), ApiParameter(name: 'onPressed', type: 'VoidCallback?', isRequired: true, isNamed: true, defaultValue: '', doc: 'Called when the button is pressed; null disables the button.'), ApiParameter(name: 'tooltip', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The tooltip, also used as the accessibility label.'), ApiParameter(name: 'isSelected', type: 'bool?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Whether the toggle is on; null makes a plain button.'), ApiParameter(name: 'selectedIcon', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The icon shown while [isSelected] is true.'), ApiParameter(name: 'focusNode', type: 'FocusNode?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The focus node; one is created when null.'), ApiParameter(name: 'autofocus', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether the button takes focus when first shown.')])], properties: [], methods: [], values: []),
