  'Oito2JsonTreeView': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A tree view of decoded JSON [data], with keys, strings, numbers,\nbooleans and null in the theme\'s syntax colors, and the size of each\nobject and list.\n\nBranches up to [expandDepth] levels deep start open. It has the\nkeyboard and filtering of [Oito2TreeView]; [query] filters by key and\nvalue.', signature: '', constructors: [ApiConstructor(name: 'Oito2JsonTreeView', doc: 'Creates a JSON tree view.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'data', type: 'Object?', isRequired: true, isNamed: true, defaultValue: '', doc: 'The decoded JSON: maps, lists, strings, numbers, booleans and null.'), ApiParameter(name: 'expandDepth', type: 'int', isRequired: false, isNamed: true, defaultValue: '1', doc: 'The depth up to which branches start open; 0 keeps every branch\nclosed. The tree opens to it again when [data] or this changes.'), ApiParameter(name: 'rootLabel', type: 'String', isRequired: false, isNamed: true, defaultValue: '\'root\'', doc: 'The label of the top node.'), ApiParameter(name: 'query', type: 'String', isRequired: false, isNamed: true, defaultValue: '\'\'', doc: 'The text that filters the nodes.'), ApiParameter(name: 'semanticLabel', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The accessibility label of the tree.')])], properties: [], methods: [], values: []),
  'Oito2KeyChord': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'One key press of a shortcut: a [key] with modifiers.\n\n[primary] stands for the platform\'s main shortcut modifier: Command on\nmacOS and iOS, Control elsewhere. Shortcuts written with it, such as\n`Mod+K`, read naturally on every platform.', signature: '', constructors: [ApiConstructor(name: 'Oito2KeyChord', doc: 'Creates a chord.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'key', type: 'LogicalKeyboardKey', isRequired: true, isNamed: false, defaultValue: '', doc: 'The key, without modifiers.'), ApiParameter(name: 'primary', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether the platform\'s primary modifier is held.'), ApiParameter(name: 'control', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether Control is held.'), ApiParameter(name: 'shift', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether Shift is held.'), ApiParameter(name: 'alt', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether Alt (Option on Apple keyboards) is held.'), ApiParameter(name: 'meta', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether Meta (Command on Apple keyboards, Super elsewhere) is held.')]), ApiConstructor(name: 'Oito2KeyChord.fromEvent', doc: 'Creates the chord of [event]\'s key with the modifiers that\n[HardwareKeyboard] reports as held, with numpad Enter read as Enter.\n\nThe chord sets [control] and [meta] as pressed, never [primary];\n[matches] resolves [primary] when comparing.', isConst: false, isFactory: true, parameters: [ApiParameter(name: 'event', type: 'KeyEvent', isRequired: true, isNamed: false, defaultValue: '', doc: '')])], properties: [ApiMember(name: 'hasCommandModifier', signature: 'bool', doc: 'Whether the chord holds a modifier other than Shift, so it can\'t be\ntyped as text.')], methods: [ApiMember(name