  'Oito2LinearProgressIndicator': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A linear progress indicator painted in the oito2 style.\n\nWith a [value] from 0 to 1, a bar fills the track from the start side.\nWithout one, a short segment glides back and forth along the track, as\nGNOME\'s pulse; when animations are disabled it stays still. The bar\nand the track have round ends and fill the available width, or 160\npixels when the width is unbounded.\n\nColors and height default to the theme\'s\n[Oito2ProgressIndicatorThemeData].', signature: '', constructors: [ApiConstructor(name: 'Oito2LinearProgressIndicator', doc: 'Creates a linear progress indicator.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'value', type: 'double?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The progress from 0 to 1, or null for indeterminate progress.'), ApiParameter(name: 'height', type: 'double?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The bar height.'), ApiParameter(name: 'color', type: 'Color?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The progress color.'), ApiParameter(name: 'trackColor', type: 'Color?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The track color.'), ApiParameter(name: 'semanticsLabel', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The accessibility label, such as what is loading.'), ApiParameter(name: 'semanticsValue', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The accessibility value; defaults to the percentage of [value].')])], properties: [], methods: [], values: []),
  'Oito2ListBox': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A list of the items of [collection] that the user selects from, with\nthe selection kept in [controller].\n\nThe list takes the focus as a whole and marks its active row. The\narrow keys, Home and End move the active row, which a single-selection\nlist also selects. In a multiple-selection list Space toggles the\nactive row, Shift with the arrows extends the selection and Control\n(Command on Apple platforms) with A selects all; clicks follow the\ndesktop conventions of [Oito2SelectionController.click]. Typing letters\njumps to the next matching label. Enter or a double click calls\n[onActivate]. Grouped items show under their group headings; disabled\nitems can\'t be selected or activated.\n\nEvery row is built, so it suits lists of up to a few hundred items.', signature: '', constructors: [ApiConstructor(name: 'Oito2ListBox', doc: 'Creates a list box.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'collection', type: 'Oito2ListCollection<T>', isRequired: true, isNamed: true, defaultValue: '', doc: 'The items.'), ApiParameter(name: 'controller', type: 'Oito2SelectionController', isRequired: true, isNamed: true, defaultValue: '', doc: 'The selection over [collection].'), ApiParameter(name: 'itemBuilder', type: 'Oito2ListBoxItemBuilder<T>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Builds the content of a row; shows the item label when null.'), ApiParameter(name: 'onActivate', type: 'ValueChanged<T>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called on Enter or a double click on an enabled item.'), ApiParameter(name: 'maxHeight', type: 'double', isRequired: false, isNamed: true, defaultValue: 'double.infinity', doc: 'The largest height; the list scrolls beyond it.'), ApiParameter(name: 'semanticLabel', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The accessibility label of the list.'), ApiParameter(name: 'autofocus',