  'Oito2ListCollection': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'An immutable list of items with the accessors a list, select or\nautocomplete needs: a unique string value, a display label, a disabled\nflag and an optional group per item.\n\nNavigation methods skip disabled items. Methods that change the list\nreturn a new collection.', signature: '', constructors: [ApiConstructor(name: 'Oito2ListCollection', doc: 'Creates a collection of [items].\n\n[valueOf] gives each item\'s unique value and defaults to the item\nitself when it is a [String], or its `toString()` otherwise.\n[labelOf] defaults to [valueOf]. Items are enabled unless\n[isDisabled] says otherwise, and ungrouped unless [groupOf] returns\na group name.\n\nThrows an [ArgumentError] when two items share a value.', isConst: false, isFactory: false, parameters: [ApiParameter(name: 'items', type: 'Iterable<T>', isRequired: true, isNamed: false, defaultValue: '', doc: ''), ApiParameter(name: 'valueOf', type: 'String Function(T)?', isRequired: false, isNamed: true, defaultValue: '', doc: ''), ApiParameter(name: 'labelOf', type: 'String Function(T)?', isRequired: false, isNamed: true, defaultValue: '', doc: ''), ApiParameter(name: 'isDisabled', type: 'bool Function(T)?', isRequired: false, isNamed: true, defaultValue: '', doc: ''), ApiParameter(name: 'groupOf', type: 'String? Function(T)?', isRequired: false, isNamed: true, defaultValue: '', doc: '')])], properties: [ApiMember(name: 'length', signature: 'int', doc: 'The number of items.'), ApiMember(name: 'isEmpty', signature: 'bool', doc: 'Whether the collection has no items.'), ApiMember(name: 'values', signature: 'List<String>', doc: 'The values of every item, in order.'), ApiMember(name: 'firstValue', signature: 'String?', doc: 'The value of the first enabled item, or null.'), ApiMember(name: 'lastValue', signature: 'String?', doc: 'The value of the last enabled item, or null.'), ApiMember(name: 'groups', signature: 'List<({String? group, List<T> items})>', doc: 'The items grouped by [groupOf], in the order each group first\nappears; ungrouped items form a group named null.')], methods: [ApiMember(name: 'valueOf', signature: 'valueOf(T item) → String', doc: 'Returns the unique value of [item].'), ApiMember(name: 'labelOf', signature: 'labelOf(T item) → String', doc: 'Returns the display label of [item].'), ApiMember(name: 'isDisabled', signature: 'isDisabled(T item) → bool', doc: 'Whether [item] can\'t be selected or focused.'), ApiMember(name: 'groupOf', signature: 'groupOf(T item) → String?', doc: 'Returns the group of [item], or null when it has none.'), ApiMember(name: 'has', signature: 'has(String? value) → bool', doc: 'Whether an item has [value].'), ApiMember(name: 'indexOf', signature: 'indexOf(String? value) → int', doc: 'Returns the index of the item with [value], or -1 when there is none.'), ApiMember(name: 'find', signature: 'find(String? value) → T?', doc: 'Returns the item with [value], or null when there is none.'), ApiMember(name: 'isEnabled', signature: 'isEnabled(String? value) → bool', doc: 'Whether the item with [value] exists and is enabled.'), ApiMember(name: 'nextValue', signature: 'nextValue(String value, bool loop) → String?', doc: 'Returns the value of the first enabled item after [value], or null at\nthe end. With [loop], the search wraps around to the start.\n\nWhen [value] isn\'t in the collection, the search starts before the\nfirst item.'), ApiMember(name: 'previousValue', signature: 'previousValue(String value, bool loop) → String?', doc: 'Returns the value of the first enabled item before [value], or null\nat the start. With [loop], the search wraps around to the end.\n\nWhen [value] isn\'t in the collection, the search starts after the\nlast item.'), ApiMember(name: 'search', signature: 'search(String query, String? from) → String?', doc: 'Returns the value of the first enabled item whose label starts with\n[query], ignoring case and accents, searching after the item with