  'Oito2ListTile': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'An interactive row with a title, an optional subtitle and widgets on\nboth sides, styled for desktop lists and settings pages.\n\nUnlike [Oito2Tile], it is meant to be activated: it shows hover and\nselected states, takes keyboard focus with the oito2 focus ring and\nreads as a button to assistive technologies when it has [onTap]. Use\n[Oito2ListTile.square] inside an `Oito2TileList`, whose border already\nrounds the corners.\n\nThe row is at least 40 pixels tall (52 with a subtitle) on pointer\nplatforms and 56 (72) on touch platforms.', signature: '', constructors: [ApiConstructor(name: 'Oito2ListTile', doc: 'Creates a list tile with rounded corners.\n\nThrows an [AssertionError] in debug builds when both [title] and\n[titleText], or both [subtitle] and [subtitleText], are given.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'leading', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'A widget before the title, usually an icon.'), ApiParameter(name: 'title', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The primary content.'), ApiParameter(name: 'titleText', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The primary text, as a shortcut for a [Text] [title].'), ApiParameter(name: 'subtitle', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The secondary content below the title.'), ApiParameter(name: 'subtitleText', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The secondary text, as a shortcut for a [Text] [subtitle].'), ApiParameter(name: 'trailing', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'A widget after the title, such as a switch or a chevron.'), ApiParameter(name: 'onTap', type: 'VoidCallback?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called when the row is activated; without it the ro