  'Oito2NavigationPage': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'Top-level navigation between pages that adapts to the available width\nand the input.\n\n- On touch platforms below [compactBreakpoint] wide, the destinations\n  are a bottom [NavigationBar].\n- Otherwise they are an [Oito2NavigationRail] at the start side:\n  compact (icons only) below [compactBreakpoint] on pointer platforms,\n  labelled up to [extendedBreakpoint], and extended (labels beside the\n  icons) from it. [railStyle] forces one style.\n\nBreakpoints, the rail color and padding and the separator default to\nthe theme\'s [Oito2NavigationPageThemeData]. The selected page fades in\nwhen it changes.', signature: '', constructors: [ApiConstructor(name: 'Oito2NavigationPage', doc: 'Creates a navigation page.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'items', type: 'List<Oito2NavigationItem>', isRequired: true, isNamed: true, defaultValue: '', doc: 'The destinations, in order.'), ApiParameter(name: 'pageBuilder', type: 'IndexedWidgetBuilder', isRequired: true, isNamed: true, defaultValue: '', doc: 'Builds the page of a destination.'), ApiParameter(name: 'controller', type: 'Oito2PageController?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Controls the selected destination; its length must match [items].'), ApiParameter(name: 'initialIndex', type: 'int', isRequired: false, isNamed: true, defaultValue: '0', doc: 'The destination selected at start, when no [controller] is given.'), ApiParameter(name: 'onSelected', type: 'ValueChanged<int>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called when the user selects a destination.'), ApiParameter(name: 'leading', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'A widget above the rail destinations.'), ApiParameter(name: 'trailing', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'A widget below the rail destinations.'), ApiParameter(name: 