  'Oito2NavigationRail': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A vertical bar of destinations at the start side of a window, in one\nof three [style]s: icons only, icons with labels below, or a wider rail\nwith labels beside the icons. The width animates when the style\nchanges.\n\nThe destinations scroll, with undershoot shadows, when they don\'t fit\nthe height, and the selected destination is scrolled into view when it\nchanges or first shows; [leading] and [trailing] stay at the top and\nbottom. The rail uses the chrome sidebar color unless\n[backgroundColor] is given.', signature: '', constructors: [ApiConstructor(name: 'Oito2NavigationRail', doc: 'Creates a navigation rail.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'items', type: 'List<Oito2NavigationItem>', isRequired: true, isNamed: true, defaultValue: '', doc: 'The destinations, in order.'), ApiParameter(name: 'selectedIndex', type: 'int', isRequired: true, isNamed: true, defaultValue: '', doc: 'The selected destination, or -1 for none.'), ApiParameter(name: 'onDestinationSelected', type: 'ValueChanged<int>', isRequired: true, isNamed: true, defaultValue: '', doc: 'Called with the index of an activated destination.'), ApiParameter(name: 'style', type: 'Oito2NavigationRailStyle', isRequired: false, isNamed: true, defaultValue: 'Oito2NavigationRailStyle.labelled', doc: 'How the destinations are shown.'), ApiParameter(name: 'leading', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'A widget above the destinations.'), ApiParameter(name: 'trailing', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'A widget below the destinations.'), ApiParameter(name: 'backgroundColor', type: 'Color?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The rail background; defaults to the chrome sidebar color.'), ApiParameter(name: 'padding', type: 'EdgeInsetsGeometry', isRequired: false, isNamed: true, defaultValue: 'const EdgeInse