  'Oito2NumberEntry': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A number field with decrease and increase buttons, like a GNOME spin\nbutton.\n\nIt shows [value] in the locale\'s number format with [decimals]\ndecimal places. Typed text is read when the field loses focus or on\nEnter, rounded, kept between [min] and [max], and reported through\n[onChanged]; text that isn\'t a number is replaced by the current\nvalue.\n\nWhile the entry is enabled, the Up and Down arrow keys change the value\nby [step], Page Up and Page Down by [pageStep], and Home and End jump to\n[min] and [max] when they are finite. With the focus in the field the\nmouse wheel steps too, and dragging sideways on the buttons scrubs the\nvalue one [step] per 4 pixels.', signature: '', constructors: [ApiConstructor(name: 'Oito2NumberEntry', doc: 'Creates a number entry.\n\n[pageStep] defaults to ten times [step]. Throws an [AssertionError] in\ndebug mode when [min] is greater than [max], when [step] is not\ngreater than zero, or when [decimals] is not between 0 and 20.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'value', type: 'double', isRequired: true, isNamed: true, defaultValue: '', doc: 'The current value.'), ApiParameter(name: 'onChanged', type: 'ValueChanged<double>?', isRequired: true, isNamed: true, defaultValue: '', doc: 'Called with each new value; the entry is read-only when null.'), ApiParameter(name: 'min', type: 'double', isRequired: false, isNamed: true, defaultValue: 'double.negativeInfinity', doc: 'The smallest value.'), ApiParameter(name: 'max', type: 'double', isRequired: false, isNamed: true, defaultValue: 'double.infinity', doc: 'The largest value.'), ApiParameter(name: 'step', type: 'double', isRequired: false, isNamed: true, defaultValue: '1', doc: 'The change of the arrow keys, the buttons and the wheel.'), ApiParameter(name: 'pageStep', type: 'double?', isRequired: false, isNamed: true, defaultValue: '', doc: ''), ApiParameter(name: 'decimals'