  'Oito2Pagination': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'Page navigation: previous and next buttons around page number buttons\nwith ellipses, and an optional page size selector.\n\nNarrower than [compactWidth] it shows only the buttons around "Page 3\nof 10", with the page size selector wrapped below. Pages count from 1.', signature: '', constructors: [ApiConstructor(name: 'Oito2Pagination', doc: 'Creates a pagination.\n\nThrows an [AssertionError] in debug mode when [pageCount] is less than\n1, when [page] is outside 1 to [pageCount], or when [siblingCount] or\n[boundaryCount] is negative. Building also asserts that [pageSize] is\none of [pageSizes] when both are given.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'page', type: 'int', isRequired: true, isNamed: true, defaultValue: '', doc: 'The current page, from 1.'), ApiParameter(name: 'pageCount', type: 'int', isRequired: true, isNamed: true, defaultValue: '', doc: 'The number of pages.'), ApiParameter(name: 'onChanged', type: 'ValueChanged<int>?', isRequired: true, isNamed: true, defaultValue: '', doc: 'Called with the page to show.'), ApiParameter(name: 'siblingCount', type: 'int', isRequired: false, isNamed: true, defaultValue: '1', doc: 'The pages shown on each side of the current one.'), ApiParameter(name: 'boundaryCount', type: 'int', isRequired: false, isNamed: true, defaultValue: '1', doc: 'The pages always shown at each end.'), ApiParameter(name: 'pageSize', type: 'int?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The current page size, for the selector; one of [pageSizes] when\nthey are given.'), ApiParameter(name: 'pageSizes', type: 'List<int>', isRequired: false, isNamed: true, defaultValue: 'const []', doc: 'The page sizes offered; the selector shows when it has entries.'), ApiParameter(name: 'onPageSizeChanged', type: 'ValueChanged<int>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with the chosen page size.'), ApiParameter(