  'Oito2PasswordField': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A password text field with a button that shows or hides the text and\na warning while Caps Lock is on.\n\nIt fills from password managers through [autofillHints]; use\n[AutofillHints.newPassword] for a field that sets a new password.', signature: '', constructors: [ApiConstructor(name: 'Oito2PasswordField', doc: 'Creates a password field.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'controller', type: 'TextEditingController?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The text controller; one is created when null.'), ApiParameter(name: 'focusNode', type: 'FocusNode?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The focus node; one is created when null.'), ApiParameter(name: 'labelText', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The field label.'), ApiParameter(name: 'hintText', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The hint shown while the field is empty.'), ApiParameter(name: 'errorText', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'An error shown below the field.'), ApiParameter(name: 'onChanged', type: 'ValueChanged<String>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called when the text changes.'), ApiParameter(name: 'onSubmitted', type: 'ValueChanged<String>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called when the user submits the field.'), ApiParameter(name: 'autofillHints', type: 'Iterable<String>?', isRequired: false, isNamed: true, defaultValue: 'const [AutofillHints.password]', doc: 'The autofill hints for password managers.'), ApiParameter(name: 'textInputAction', type: 'TextInputAction?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The keyboard action button.'), ApiParameter(name: 'autofocus', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether the