  'Oito2PinEntry': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A code entry drawn as [length] one-character cells, such as a PIN or\na one-time code.\n\nOne text field sits under the cells, so typing, deleting, pasting a\nwhole code and one-time code autofill all work as in any field; a\npasted code fills the cells in order. When the last cell is filled the\nentry calls [onCompleted] and gives up the focus.', signature: '', constructors: [ApiConstructor(name: 'Oito2PinEntry', doc: 'Creates a code entry.\n\nThrows an [AssertionError] in debug mode when [length] is not greater\nthan zero.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'length', type: 'int', isRequired: false, isNamed: true, defaultValue: '6', doc: 'The number of characters.'), ApiParameter(name: 'onChanged', type: 'ValueChanged<String>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called when the code changes.'), ApiParameter(name: 'onCompleted', type: 'ValueChanged<String>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called when every cell is filled.'), ApiParameter(name: 'numeric', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether only digits are accepted.'), ApiParameter(name: 'obscure', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether the characters show as dots.'), ApiParameter(name: 'hasError', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether the cells show the error border.'), ApiParameter(name: 'controller', type: 'TextEditingController?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The text controller; one is created when null.'), ApiParameter(name: 'focusNode', type: 'FocusNode?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The focus node; one is created when null.'), ApiParameter(name: 'autofocus', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether the entry takes the 