  'Oito2PlaceholderIcon': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A decorative square that stands in for a missing picture, such as an\nalbum cover or an app icon that has not loaded.\n\nIt fills a rounded square with a container tone of the color scheme\nand draws a picture outline in its center. It is hidden from assistive\ntechnologies.', signature: '', constructors: [ApiConstructor(name: 'Oito2PlaceholderIcon', doc: 'Creates a placeholder icon.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'size', type: 'double', isRequired: false, isNamed: true, defaultValue: '48', doc: 'The width and height.'), ApiParameter(name: 'borderRadius', type: 'BorderRadius', isRequired: false, isNamed: true, defaultValue: 'Oito2Radius.mediumAll', doc: 'The corner rounding.')])], properties: [], methods: [], values: []),
  'Oito2Platform': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'Describes the platform an app runs on and the ergonomics that follow\nfrom it.\n\n[Oito2Platform.current] reads the running platform. The default\nconstructor accepts explicit values so tests and previews can simulate\nany platform.', signature: '', constructors: [ApiConstructor(name: 'Oito2Platform', doc: 'Creates a platform description from explicit values.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'targetPlatform', type: 'TargetPlatform', isRequired: true, isNamed: true, defaultValue: '', doc: 'The operating system, or the browser host operating system on the web.'), ApiParameter(name: 'isWeb', type: 'bool', isRequired: true, isNamed: true, defaultValue: '', doc: 'Whether the app runs inside a web browser.')]), ApiConstructor(name: 'Oito2Platform.current', doc: 'Creates a platform description for the running app.\n\nReads [kIsWeb] and [defaultTargetPlatform], so it honors\n`debugDefaultTargetPlatformOverride`. On the web, [targetPlatform] is\nthe operating system of the browser host.', isConst: false, isFactory: true, parameters: [])], properties: [ApiMember(name: 'isDesktopNative', signature: 'bool', doc: 'Whether the app runs as a native desktop app (Linux, Windows or\nmacOS), outside a browser.'), ApiMember(name: 'isTouch', signature: 'bool', doc: 'Whether the app runs as a native app on a touch-first operating system\n(Android, iOS or Fuchsia), outside a browser.'), ApiMember(name: 'isWebTouch', signature: 'bool', doc: 'Whether the app runs in a browser on a touch-first operating system.'), ApiMember(name: 'usesTouchInput', signature: 'bool', doc: 'Whether the primary input is touch, natively or in a browser.'), ApiMember(name: 'isLinux', signature: 'bool', doc: 'Whether the operating system is Linux.'), ApiMember(name: 'isWindows', signature: 'bool', doc: 'Whether the operating system is Windows.'), ApiMember(name: 'isMacOS', signature: 'bool', doc: 'Whether the op