  'Oito2Popover': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A non-modal panel anchored to a widget, such as a picker or a short\nform.\n\n[builder] builds the anchor and [popoverBuilder] the panel content;\nboth receive the controller, which a button in the anchor typically\ntoggles. The panel opens on the [placement] side, moving to the other\nside when it doesn\'t fit, lines up with the anchor by [alignment], and\nfollows the anchor as it moves or scrolls.\n\nThe panel closes on Escape and, with [closeOnTapOutside], on a tap\noutside the anchor and the panel. A popover opened from inside\nanother one keeps the outer one open. With [focusOnOpen] the first\nfocusable widget of the panel takes the focus when it opens; when it\ncloses with the focus inside, the focus returns to where it was.', signature: '', constructors: [ApiConstructor(name: 'Oito2Popover', doc: 'Creates a popover.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'builder', type: 'Oito2PopoverWidgetBuilder', isRequired: true, isNamed: true, defaultValue: '', doc: 'Builds the anchor.'), ApiParameter(name: 'popoverBuilder', type: 'Oito2PopoverWidgetBuilder', isRequired: true, isNamed: true, defaultValue: '', doc: 'Builds the panel content.'), ApiParameter(name: 'controller', type: 'Oito2PopoverController?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Opens and closes the panel; the popover keeps its own when null.'), ApiParameter(name: 'placement', type: 'Oito2PopoverPlacement', isRequired: false, isNamed: true, defaultValue: 'Oito2PopoverPlacement.bottom', doc: 'The preferred side of the anchor.'), ApiParameter(name: 'alignment', type: 'Oito2PopoverAlignment', isRequired: false, isNamed: true, defaultValue: 'Oito2PopoverAlignment.start', doc: 'The alignment along the anchor\'s edge.'), ApiParameter(name: 'showArrow', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether the panel points at the anchor with an arrow.'), ApiParameter(name: 'matchAnchorWidth', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether a panel above or below takes the anchor\'s width.'), ApiParameter(name: 'maxWidth', type: 'double', isRequired: false, isNamed: true, defaultValue: '360', doc: 'The largest panel width.'), ApiParameter(name: 'maxHeight', type: 'double', isRequired: false, isNamed: true, defaultValue: 'double.infinity', doc: 'The largest panel height; the content scrolls itself beyond it.'), ApiParameter(name: 'padding', type: 'EdgeInsetsGeometry', isRequired: false, isNamed: true, defaultValue: 'const EdgeInsets.all(Oito2Spacing.md)', doc: 'The space around the content inside the panel.'), ApiParameter(name: 'closeOnTapOutside', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether a tap outside the anchor and the panel closes the panel.'), ApiParameter(name: 'focusOnOpen', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether the panel takes the focus when it opens.'), ApiParameter(name: 'onOpenChanged', type: 'ValueChanged<bool>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called when the panel opens or closes.'), ApiParameter(name: 'semanticLabel', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The accessibility label of the panel.')])], properties: [], methods: [], values: []),
