  'Oito2PopupMenuButton': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A button that looks like a field and opens a menu of [menuChildren]\nbelow it, for choices that don\'t fit a segmented button.\n\nThe button is as tall as the text fields, shows [child] and a chevron,\nand opens the menu on a click, Enter, Space or the Down arrow; the menu\nis a `MenuAnchor`, navigated with the arrow keys. Use\n[Oito2CheckedMenuItem] and [Oito2MultiSelectMenuItem] for choices, or\n[Oito2Select] for a value picked from a collection.', signature: '', constructors: [ApiConstructor(name: 'Oito2PopupMenuButton', doc: 'Creates a popup menu button.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'child', type: 'Widget', isRequired: true, isNamed: true, defaultValue: '', doc: 'The button content, usually the current choice as a [Text].'), ApiParameter(name: 'menuChildren', type: 'List<Widget>', isRequired: true, isNamed: true, defaultValue: '', doc: 'The menu entries.'), ApiParameter(name: 'enabled', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether the button opens its menu.'), ApiParameter(name: 'leading', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'An optional icon before [child].'), ApiParameter(name: 'tooltip', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'A tooltip for the button.'), ApiParameter(name: 'semanticLabel', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The accessibility label; defaults to the text of [child].'), ApiParameter(name: 'focusNode', type: 'FocusNode?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The focus node of the button.')])], properties: [], methods: [], values: []),
