  'Oito2Radio': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A radio button painted in the oito2 style.\n\nIt is selected when [value] equals [groupValue]. The ring has a\n1.5-pixel `outline` border while unselected and fills with the\nprimary tone when selected, with a dot in its on-color. With\n[toggleable], tapping the selected radio clears the group (calls\n[onChanged] with null). Space and Enter select it while focused.\n\nThe ring is 20 pixels on pointer platforms and 24 on touch platforms.', signature: '', constructors: [ApiConstructor(name: 'Oito2Radio', doc: 'Creates a radio button.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'value', type: 'T', isRequired: true, isNamed: true, defaultValue: '', doc: 'The value this radio represents.'), ApiParameter(name: 'groupValue', type: 'T?', isRequired: true, isNamed: true, defaultValue: '', doc: 'The currently selected value of the group.'), ApiParameter(name: 'onChanged', type: 'ValueChanged<T?>?', isRequired: true, isNamed: true, defaultValue: '', doc: 'Called with [value] when selected, or null when a [toggleable] radio\nis cleared; null disables the radio.'), ApiParameter(name: 'toggleable', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether tapping the selected radio clears the group by calling\n[onChanged] with null.'), ApiParameter(name: 'focusNode', type: 'FocusNode?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The focus node; one is created when null.'), ApiParameter(name: 'autofocus', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether the radio takes focus when first shown.'), ApiParameter(name: 'semanticLabel', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The accessibility label, when no surrounding label provides one.')])], properties: [], methods: [], values: []),
