  'Oito2RangeSlider': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A slider for a range between two values, with an optional [label] and\nvalue text above the track and [marks] along it.\n\nIt is a Material `RangeSlider` drawn like [Oito2Slider]. [valueText]\nformats each end for the text above the track (as "start – end") and\nthe indicators shown while dragging (with [showValueIndicator]).', signature: '', constructors: [ApiConstructor(name: 'Oito2RangeSlider', doc: 'Creates a range slider.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'values', type: 'RangeValues', isRequired: true, isNamed: true, defaultValue: '', doc: 'The selected range, between [min] and [max].'), ApiParameter(name: 'onChanged', type: 'ValueChanged<RangeValues>?', isRequired: true, isNamed: true, defaultValue: '', doc: 'Called with the new range while it changes; null disables the slider.'), ApiParameter(name: 'onChangeStart', type: 'ValueChanged<RangeValues>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with the range when a change starts.'), ApiParameter(name: 'onChangeEnd', type: 'ValueChanged<RangeValues>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with the range when a change ends.'), ApiParameter(name: 'min', type: 'double', isRequired: false, isNamed: true, defaultValue: '0', doc: 'The smallest value.'), ApiParameter(name: 'max', type: 'double', isRequired: false, isNamed: true, defaultValue: '1', doc: 'The largest value.'), ApiParameter(name: 'divisions', type: 'int?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The number of equal steps between [min] and [max]; null for a\ncontinuous slider.'), ApiParameter(name: 'label', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The name shown above the track.'), ApiParameter(name: 'valueText', type: 'String Function(double)?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Formats a value; when given, the range shows ab