  'Oito2Rating': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A row of [max] stars showing [value], which the user can change by\nclicking, tapping or with the keyboard.\n\nWith [allowHalf] the value moves in halves: the start half of a star\ngives the half value. Hovering previews the value under the pointer.\nThe arrow keys change the value by one step, Home and End jump to 0\nand [max], and the digit keys 0 to 9 pick that whole value, up to\n[max]. A star animates when it fills. Assistive technologies see it as\na slider.', signature: '', constructors: [ApiConstructor(name: 'Oito2Rating', doc: 'Creates a rating.\n\nThrows an [AssertionError] in debug mode when [max] is not greater\nthan zero or [value] is outside 0 to [max].', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'value', type: 'double', isRequired: true, isNamed: true, defaultValue: '', doc: 'The current value, from 0 to [max].'), ApiParameter(name: 'onChanged', type: 'ValueChanged<double>?', isRequired: true, isNamed: true, defaultValue: '', doc: 'Called with each new value; the rating is read-only when null.'), ApiParameter(name: 'max', type: 'int', isRequired: false, isNamed: true, defaultValue: '5', doc: 'The number of stars.'), ApiParameter(name: 'allowHalf', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether half values can be picked.'), ApiParameter(name: 'size', type: 'double', isRequired: false, isNamed: true, defaultValue: '24', doc: 'The star size.'), ApiParameter(name: 'color', type: 'Color?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The filled star color; defaults to the theme\'s warning color.'), ApiParameter(name: 'semanticLabel', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The accessibility label, such as what is rated.')])], properties: [], methods: [], values: []),
  'Oito2ScrollArea': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A scrollable box for a [child] larger than it, with the themed scroll\nbars on the axes it scrolls in.\n\nThe bars show while scrolling or, with [thumbVisibility], all the time.\nWith [undershoot], an [Oito2ScrollViewUndershoot] shadow marks the\nedges with more content beyond them; with\n[Oito2ScrollDirection.both], the shadows follow the vertical axis.', signature: '', constructors: [ApiConstructor(name: 'Oito2ScrollArea', doc: 'Creates a scroll area.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'child', type: 'Widget', isRequired: true, isNamed: true, defaultValue: '', doc: 'The content.'), ApiParameter(name: 'direction', type: 'Oito2ScrollDirection', isRequired: false, isNamed: true, defaultValue: 'Oito2ScrollDirection.vertical', doc: 'The directions the content scrolls in.'), ApiParameter(name: 'verticalController', type: 'ScrollController?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The controller of the vertical scroll position; one is created when\nnull.'), ApiParameter(name: 'horizontalController', type: 'ScrollController?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The controller of the horizontal scroll position; one is created when\nnull.'), ApiParameter(name: 'thumbVisibility', type: 'bool?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Whether the scroll bars always show; null follows the scroll bar\ntheme.'), ApiParameter(name: 'undershoot', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether a soft shadow marks the edges with more content beyond them.'), ApiParameter(name: 'padding', type: 'EdgeInsetsGeometry?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The space around [child], inside the scrolled content.')])], properties: [], methods: [], values: []),
