  'Oito2ScrollViewUndershoot': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'Fades a soft shadow in at the start and end edges of a scrollable\n[child] while there is more content beyond them.\n\nWorks with any scroll view below it; no controller is needed. With\n[pointerScrolling], a horizontal scroll view also scrolls with the\nvertical mouse wheel and with mouse drags, which Flutter leaves to\nShift+wheel and touch by default.', signature: '', constructors: [ApiConstructor(name: 'Oito2ScrollViewUndershoot', doc: 'Creates a scroll undershoot.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'child', type: 'Widget', isRequired: true, isNamed: true, defaultValue: '', doc: 'The scroll view.'), ApiParameter(name: 'start', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether the shadow at the start edge is shown.'), ApiParameter(name: 'end', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether the shadow at the end edge is shown.'), ApiParameter(name: 'extent', type: 'double', isRequired: false, isNamed: true, defaultValue: 'Oito2Spacing.md', doc: 'The depth of the shadows, in logical pixels.'), ApiParameter(name: 'pointerScrolling', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether a horizontal scroll view below scrolls with the vertical\nmouse wheel and with mouse drags.')])], properties: [], methods: [], values: []),
  'Oito2SearchField': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A search text field with a search icon and a clear button that appears\nwhile it has text.\n\nPressing Escape clears the text; pressing it again on an empty field\ncalls [onEscape]. The hint and the clear button tooltip come from\n`MaterialLocalizations`, so they follow the app language.', signature: '', constructors: [ApiConstructor(name: 'Oito2SearchField', doc: 'Creates a search field.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'controller', type: 'TextEditingController?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Controls the text; one is created when null.'), ApiParameter(name: 'focusNode', type: 'FocusNode?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The focus node of the text field.'), ApiParameter(name: 'hintText', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The hint; defaults to the localized "Search".'), ApiParameter(name: 'onChanged', type: 'ValueChanged<String>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called whenever the text changes.'), ApiParameter(name: 'onSubmitted', type: 'ValueChanged<String>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called when the user submits the text.'), ApiParameter(name: 'onClear', type: 'VoidCallback?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called after the clear button or Escape empties the field.'), ApiParameter(name: 'onEscape', type: 'VoidCallback?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called when Escape is pressed on an empty field.'), ApiParameter(name: 'autofocus', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether the field takes focus when shown.'), ApiParameter(name: 'prefixIcon', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The widget before the text; defaults to a search icon.')])], properties: [], methods: [], values: []),
  'Oito2SearchTitleField': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A title bar element that switches between a [title] and a search\nfield, with a toggle button, as in GNOME apps.\n\nThe element keeps the same size in both states: a box [fieldWidth]\nwide and as tall as a field, with the toggle button at its start.\nWhile the search is closed, the [title] follows the button; while it\nis open, the search field fills the box and the button serves as its\nsearch icon. Only the content fades, so the surrounding layout never\nmoves.\n\nEscape on an empty field closes the search and returns focus to the\ntoggle button. The toggle button reports its pressed state to\nassistive technologies.', signature: '', constructors: [ApiConstructor(name: 'Oito2SearchTitleField', doc: 'Creates a search title field.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'title', type: 'Widget', isRequired: true, isNamed: true, defaultValue: '', doc: 'Shown while the search is closed.'), ApiParameter(name: 'searchActive', type: 'bool', isRequired: true, isNamed: true, defaultValue: '', doc: 'Whether the search field is shown.'), ApiParameter(name: 'onSearchActiveChanged', type: 'ValueChanged<bool>', isRequired: true, isNamed: true, defaultValue: '', doc: 'Called to open or close the search.'), ApiParameter(name: 'onChanged', type: 'ValueChanged<String>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called whenever the search text changes.'), ApiParameter(name: 'onSubmitted', type: 'ValueChanged<String>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called when the user submits the search text.'), ApiParameter(name: 'controller', type: 'TextEditingController?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Controls the search text.'), ApiParameter(name: 'hintText', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The search hint; defaults to the localized "Search".'), ApiParameter(name: 'fieldWidth',