  'Oito2Section': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A titled group of content: a headline with optional actions above a\n[Oito2BorderContainer].', signature: '', constructors: [ApiConstructor(name: 'Oito2Section', doc: 'Creates a section.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'headline', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The section title, usually a [Text]; exposed as a header to\nassistive technologies.'), ApiParameter(name: 'actions', type: 'List<Widget>', isRequired: false, isNamed: true, defaultValue: 'const []', doc: 'Widgets placed at the end of the headline row, such as buttons.'), ApiParameter(name: 'child', type: 'Widget', isRequired: true, isNamed: true, defaultValue: '', doc: 'The section content.'), ApiParameter(name: 'padding', type: 'EdgeInsetsGeometry', isRequired: false, isNamed: true, defaultValue: 'const EdgeInsets.all(Oito2Spacing.lg)', doc: 'Space inside the bordered container.'), ApiParameter(name: 'margin', type: 'EdgeInsetsGeometry?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Space around the whole section.')])], properties: [], methods: [], values: []),
