  'Oito2SelectionController': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'The selected values of an [Oito2ListCollection], with the desktop\nselection gestures: plain click, Control/Command click to toggle and\nShift click to extend a range from the anchor.\n\nDisabled items and values outside the collection are never selected.\n[selectedValues] keeps the collection order.', signature: '', constructors: [ApiConstructor(name: 'Oito2SelectionController', doc: 'Creates a selection over [collection] with [initialValues].\n\nInitial values that [canSelect] rejects are dropped, and in single\nmode only the first remaining value in collection order is kept.', isConst: false, isFactory: false, parameters: [ApiParameter(name: 'collection', type: 'Oito2ListCollection<Object?>', isRequired: true, isNamed: true, defaultValue: '', doc: ''), ApiParameter(name: 'mode', type: 'Oito2SelectionMode', isRequired: false, isNamed: true, defaultValue: 'Oito2SelectionMode.single', doc: 'How many items can be selected.'), ApiParameter(name: 'deselectable', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether a selected item can be deselected by clicking it again in\nsingle mode, or by toggling it.'), ApiParameter(name: 'resetOnCollectionChange', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether replacing the [collection] clears the selection; otherwise\nonly the values that left the collection are dropped.'), ApiParameter(name: 'initialValues', type: 'Iterable<String>', isRequired: false, isNamed: true, defaultValue: 'const []', doc: '')])], properties: [ApiMember(name: 'selectedValues', signature: 'List<String>', doc: 'The selected values, in collection order.'), ApiMember(name: 'isEmpty', signature: 'bool', doc: 'Whether nothing is selected.'), ApiMember(name: 'firstSelectedValue', signature: 'String?', doc: 'The first selected value in collection order, or null.'), ApiMember(name: 'lastSelectedValue', signature: 'String?', doc: 'The last selected value in collection order, or null.'), ApiMember(name: 'anchorValue', signature: 'String?', doc: 'The value range selections extend from: the last value selected by\n[select], [toggle] or [replace].'), ApiMember(name: 'isAllSelected', signature: 'bool', doc: 'Whether every enabled item is selected.'), ApiMember(name: 'isSomeSelected', signature: 'bool', doc: 'Whether some, but not all, enabled items are selected; drives a\nmixed "select all" check box.')], methods: [ApiMember(name: 'isSelected', signature: 'isSelected(String? value) → bool', doc: 'Whether [value] is selected.'), ApiMember(name: 'canSelect', signature: 'canSelect(String value) → bool', doc: 'Whether [value] can be selected: it is an enabled item and the mode\nallows selection.'), ApiMember(name: 'select', signature: 'select(String value, bool forceToggle) → void', doc: 'Selects [value] and makes it the anchor; does nothing when\n[canSelect] rejects it.\n\nIn multiple mode it adds [value] to the selection. In single mode it\nreplaces the selection; selecting the selected value again deselects\nit when [deselectable] and [forceToggle] are set.'), ApiMember(name: 'deselect', signature: 'deselect(String value) → void', doc: 'Deselects [value].'), ApiMember(name: 'toggle', signature: 'toggle(String value) → void', doc: 'Selects [value] when it isn\'t selected, otherwise deselects it if\n[deselectable]. [value] becomes the anchor when the selection\nchanges.'), ApiMember(name: 'replace', signature: 'replace(String? value) → void', doc: 'Makes [value] the only selected value and the anchor; null clears the\nselection. Does nothing when [canSelect] rejects [value].'), ApiMember(name: 'extend', signature: 'extend(String anchorValue, String targetValue) → void', doc: 'Selects the enabled values from [anchorValue] to [targetValue], both\nincluded, replacing the previous selection and keeping [anchorValue]\nas the anchor. Does nothing when either value isn\'t in the\ncollection. I