  'Oito2Shortcut': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A keyboard shortcut: one [Oito2KeyChord], or a sequence of chords\npressed one after the other, such as `G` then `H`.', signature: '', constructors: [ApiConstructor(name: 'Oito2Shortcut', doc: 'Creates a shortcut from [chords].\n\nThrows an [AssertionError] in debug mode when [chords] is empty.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'chords', type: 'List<Oito2KeyChord>', isRequired: true, isNamed: false, defaultValue: '', doc: 'The chords, pressed in order.')]), ApiConstructor(name: 'Oito2Shortcut.primary', doc: 'Creates a single-chord shortcut of [key] with the platform\'s primary\nmodifier (Command on Apple platforms, Control elsewhere), plus Shift\nwhen [shift] and Alt when [alt].', isConst: false, isFactory: false, parameters: [ApiParameter(name: 'key', type: 'LogicalKeyboardKey', isRequired: true, isNamed: false, defaultValue: '', doc: ''), ApiParameter(name: 'shift', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: ''), ApiParameter(name: 'alt', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: '')]), ApiConstructor(name: 'Oito2Shortcut.parse', doc: 'Parses a shortcut such as `Mod+K`, `Ctrl+Shift+P`, `Alt+Enter` or the\nsequence `G H`: chords are separated by spaces and keys within a\nchord by `+`.\n\nModifier names: `Mod`/`Primary` (Command on Apple platforms, Control\nelsewhere), `Ctrl`/`Control`, `Shift`, `Alt`/`Option`,\n`Meta`/`Cmd`/`Command`/`Super`. Keys: letters, digits, `F1`–`F12`,\n`Enter`, `Esc`, `Space`, `Tab`, `Backspace`, `Delete`, `Up`, `Down`,\n`Left`, `Right`, `Home`, `End`, `PageUp`, `PageDown` and the\npunctuation `,` `.` `/` `;` `-` `=` `[` `]`. Names are case\ninsensitive.\n\nThrows a [FormatException] when a key or modifier name is unknown,\nincluding an empty [text].', isConst: false, isFactory: true, parameters: [ApiParameter(name: 'text', type: 'String', isRequired: true, isNamed: false,