  'Oito2ShortcutLabel': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'Shows a keyboard shortcut as key caps, in the notation of the\nplatform: `⇧⌘K` on macOS and iOS, `Ctrl` `Shift` `K` elsewhere.\n\nAssistive technologies read the shortcut as text, such as\n"Ctrl+Shift+K".', signature: '', constructors: [ApiConstructor(name: 'Oito2ShortcutLabel', doc: 'Creates a shortcut label.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'shortcut', type: 'Oito2Shortcut', isRequired: true, isNamed: false, defaultValue: '', doc: 'The shortcut to show.'), ApiParameter(name: 'platform', type: 'TargetPlatform?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The platform whose notation is used; defaults to the theme\'s\n[ThemeData.platform].')])], properties: [], methods: [], values: []),
  'Oito2ShortcutRecorder': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A field that records a single-chord keyboard shortcut, as in keyboard\nsettings.\n\nClicking it, or pressing Enter or Space while it has focus, starts\nrecording; the next key with its modifiers becomes the shortcut. Escape\ncancels, and Backspace or Delete without modifiers clears the shortcut.\nA Command (Apple platforms) or Control (elsewhere) chord is stored with\nthe platform-neutral primary modifier, so it reads naturally on every\nplatform.', signature: '', constructors: [ApiConstructor(name: 'Oito2ShortcutRecorder', doc: 'Creates a shortcut recorder.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'value', type: 'Oito2Shortcut?', isRequired: true, isNamed: true, defaultValue: '', doc: 'The recorded shortcut, or null.'), ApiParameter(name: 'onChanged', type: 'ValueChanged<Oito2Shortcut?>?', isRequired: true, isNamed: true, defaultValue: '', doc: 'Called with the new shortcut, or null when it is cleared; the\nrecorder is disabled when this is null.'), ApiParameter(name: 'focusNode', type: 'FocusNode?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The focus node of the recording field; one is created and owned by\nthe recorder when null.'), ApiParameter(name: 'autofocus', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether the recorder takes focus when first shown.')])], properties: [], methods: [], values: []),
