  'Oito2Slider': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A slider for one value, with an optional [label] and value text above\nthe track and [marks] along it.\n\nIt is a Material `Slider` drawn with a thick rounded track and a ring\nthumb, so it keeps the keyboard, pointer and accessibility behavior of\n`Slider`. [valueText] formats the value for the text above the track,\nthe indicator shown while dragging (with [showValueIndicator]) and\nassistive technologies. An [Axis.vertical] slider is [length] pixels\ntall, with its minimum at the bottom.', signature: '', constructors: [ApiConstructor(name: 'Oito2Slider', doc: 'Creates a slider.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'value', type: 'double', isRequired: true, isNamed: true, defaultValue: '', doc: 'The selected value, between [min] and [max].'), ApiParameter(name: 'onChanged', type: 'ValueChanged<double>?', isRequired: true, isNamed: true, defaultValue: '', doc: 'Called with the new value while it changes; null disables the slider.'), ApiParameter(name: 'onChangeStart', type: 'ValueChanged<double>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with the value when a change starts.'), ApiParameter(name: 'onChangeEnd', type: 'ValueChanged<double>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with the value when a change ends.'), ApiParameter(name: 'min', type: 'double', isRequired: false, isNamed: true, defaultValue: '0', doc: 'The smallest value.'), ApiParameter(name: 'max', type: 'double', isRequired: false, isNamed: true, defaultValue: '1', doc: 'The largest value.'), ApiParameter(name: 'divisions', type: 'int?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The number of equal steps between [min] and [max]; null for a\ncontinuous slider.'), ApiParameter(name: 'label', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The name shown above the track.'), ApiParameter(name: 'valueText', type: 'S