  'Oito2Steps': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A step indicator: [steps] in order, those before [current] completed,\nwith the content of the current step.\n\nA step is tapped to move to it through [onStepTapped]. With [linear]\nonly the completed steps and the current one can be reached; otherwise\nany step can. The steps run in a row with the content below, or in a\ncolumn with the content under the current step.', signature: '', constructors: [ApiConstructor(name: 'Oito2Steps', doc: 'Creates a step indicator.\n\nThrows an [AssertionError] in debug mode when [current] is negative.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'steps', type: 'List<Oito2Step>', isRequired: true, isNamed: true, defaultValue: '', doc: 'The steps.'), ApiParameter(name: 'current', type: 'int', isRequired: true, isNamed: true, defaultValue: '', doc: 'The index of the current step; [steps].length when all are done.'), ApiParameter(name: 'onStepTapped', type: 'ValueChanged<int>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with the index of a tapped step that can be reached.'), ApiParameter(name: 'axis', type: 'Axis', isRequired: false, isNamed: true, defaultValue: 'Axis.horizontal', doc: 'Whether the steps run in a row or a column.'), ApiParameter(name: 'linear', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether only completed steps and the current one can be reached.')])], properties: [], methods: [], values: []),
