  'Oito2Switch': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A switch painted in the oito2 style.\n\nThe track is the highest surface container with an `outline` border\nwhile off and the primary tone while on; the thumb slides to\nthe end side (the right in left-to-right layouts). With [onOffShapes],\nthe track also shows an "I" while on and an "O" while off, so the state\ndoesn\'t rely on color. Space and Enter toggle it while focused.\n\nThe track is 42 × 24 pixels on pointer platforms and 52 × 30 on touch\nplatforms.', signature: '', constructors: [ApiConstructor(name: 'Oito2Switch', doc: 'Creates a switch.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'value', type: 'bool', isRequired: true, isNamed: true, defaultValue: '', doc: 'Whether the switch is on.'), ApiParameter(name: 'onChanged', type: 'ValueChanged<bool>?', isRequired: true, isNamed: true, defaultValue: '', doc: 'Called with the new value; null disables the switch.'), ApiParameter(name: 'onOffShapes', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether the track marks the on and off states with an "I" and an "O",\nso the state doesn\'t rely on color alone.'), ApiParameter(name: 'focusNode', type: 'FocusNode?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The focus node; one is created when null.'), ApiParameter(name: 'autofocus', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether the switch takes focus when first shown.'), ApiParameter(name: 'semanticLabel', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The accessibility label, when no surrounding label provides one.')])], properties: [], methods: [], values: []),
