  'Oito2Tab': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A tab of an [Oito2TabBar]: a [label] with an optional [icon] beside\nit. A label wider than the tab ends with an ellipsis.', signature: '', constructors: [ApiConstructor(name: 'Oito2Tab', doc: 'Creates a tab.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'label', type: 'Widget', isRequired: true, isNamed: true, defaultValue: '', doc: 'The tab label, usually a [Text].'), ApiParameter(name: 'icon', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'An icon before the label.')])], properties: [], methods: [], values: []),
  'Oito2TabBar': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A row of tabs with a rounded marker behind the selected one, a pill as\nin GNOME view switchers by default.\n\nIt drives a [TabController] like Material\'s `TabBar`: the [controller]\ngiven, or the closest `DefaultTabController`. The marker slides between\ntabs; [style] picks its look. Throws a [FlutterError] in debug builds\nwhen neither [controller] nor a `DefaultTabController` is available.', signature: '', constructors: [ApiConstructor(name: 'Oito2TabBar', doc: 'Creates a tab bar.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'tabs', type: 'List<Widget>', isRequired: true, isNamed: true, defaultValue: '', doc: 'The tabs, usually [Oito2Tab]s.'), ApiParameter(name: 'controller', type: 'TabController?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The tab controller; defaults to the closest `DefaultTabController`.'), ApiParameter(name: 'onTap', type: 'ValueChanged<int>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with the index of a tapped tab.'), ApiParameter(name: 'isScrollable', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether the tabs keep their own width and scroll, instead of sharing\nthe bar width equally. The [Oito2TabBarStyle.subtle] style always\nscrolls, whatever this value.'), ApiParameter(name: 'tabHeight', type: 'double', isRequired: false, isNamed: true, defaultValue: 'Oito2Sizes.touchButtonHeight', doc: 'The tab height that [preferredSize] reserves: the touch height by\ndefault, which fits every platform. [Oito2Sizes.buttonHeight] fits\npointer platforms exactly. The tabs size themselves from the theme\'s\ntap target size, not from this value.'), ApiParameter(name: 'style', type: 'Oito2TabBarStyle', isRequired: false, isNamed: true, defaultValue: 'Oito2TabBarStyle.pill', doc: 'The look of the selected tab marker.')])], properties: [], methods: [], values: []),
