  'Oito2TableOfContents': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A list of the sections of a scroll view that highlights the section in\nview and scrolls to a section when it is picked.\n\nThe current section is the last one whose heading has reached\n[activationOffset] pixels below the top of the viewport, or the last\nsection when the view is scrolled to the end. [controller] must be the\ncontroller of the scroll view that holds the [Oito2TocEntry.target]s.\n\nIn a lazily built scroll view, only built headings are measured: while\nnone is built the current section stays as it was, and picking a\nsection whose heading isn\'t built only calls [onSelected], which can\nscroll there.', signature: '', constructors: [ApiConstructor(name: 'Oito2TableOfContents', doc: 'Creates a table of contents.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'entries', type: 'List<Oito2TocEntry>', isRequired: true, isNamed: true, defaultValue: '', doc: 'The sections, in document order.'), ApiParameter(name: 'controller', type: 'ScrollController', isRequired: true, isNamed: true, defaultValue: '', doc: 'The controller of the scroll view the sections are in.'), ApiParameter(name: 'activationOffset', type: 'double', isRequired: false, isNamed: true, defaultValue: '32', doc: 'How far below the top of the viewport, in logical pixels, a heading\nmakes its section current.'), ApiParameter(name: 'onSelected', type: 'ValueChanged<int>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with the index of a picked section, before the view starts\nscrolling to it.')])], properties: [], methods: [], values: []),
  'Oito2TagsField': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A field of tags shown as chips, with a text input after them.\n\nEnter or a [delimiters] character adds the typed text, trimmed, as a\ntag; a pasted list is split on the delimiters. A tag is refused when it\nis empty, repeated (unless [allowDuplicates]), past [maxTags] or\nrejected by [validator]. A typed tag that is refused stays in the input\nto be fixed; the refused tags of a pasted list are dropped.\n\nBackspace in the empty input, or the start arrow with the caret at the\nstart of the input, moves to the last tag; the arrow keys move between\ntags, and Backspace or Delete removes the\nfocused one. With [suggestions], matching items not yet added show\nbelow the input as it is typed. With [clearable], a button at the end\nremoves every tag at once.', signature: '', constructors: [ApiConstructor(name: 'Oito2TagsField', doc: 'Creates a tags field.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'tags', type: 'List<String>', isRequired: true, isNamed: true, defaultValue: '', doc: 'The tags, in order.'), ApiParameter(name: 'onChanged', type: 'ValueChanged<List<String>>?', isRequired: true, isNamed: true, defaultValue: '', doc: 'Called with the new tag list after tags are added or removed; the\nfield is read-only when null.'), ApiParameter(name: 'delimiters', type: 'List<String>', isRequired: false, isNamed: true, defaultValue: 'const [\',\']', doc: 'The strings that end a tag while typing or pasting; when empty, only\nEnter adds a tag.'), ApiParameter(name: 'maxTags', type: 'int?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The largest number of tags; once reached, the input turns read-only.\nUnlimited when null.'), ApiParameter(name: 'validator', type: 'bool Function(String)?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Decides whether a trimmed, non-empty tag is accepted; every such tag\nis accepted when null.'), ApiParameter(name: 'allowDuplicates', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether the same tag can be added twice.'), ApiParameter(name: 'labelText', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The field label.'), ApiParameter(name: 'hintText', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The hint shown in the input while there are no tags.'), ApiParameter(name: 'suggestions', type: 'Oito2ListCollection<String>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The tags offered below the input while typing, excluding the tags\nalready added; no suggestions are shown when null.'), ApiParameter(name: 'focusNode', type: 'FocusNode?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The focus node of the text input; one is created when null.'), ApiParameter(name: 'style', type: 'Oito2TagsFieldStyle', isRequired: false, isNamed: true, defaultValue: 'Oito2TagsFieldStyle.filled', doc: 'The look of the tags.'), ApiParameter(name: 'clearable', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether a button at the end of the field removes every tag while the\nfield is editable and has tags.')])], properties: [], methods: [], values: []),
