  'Oito2TimeEntry': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A time text field that accepts `H:MM` and `HH:MM`, with an optional\nAM/PM suffix in 12-hour locales, and offers a clock picker button.\n\nThe display format follows the locale and the platform 24-hour\nsetting; the error message and the labels come from\n`MaterialLocalizations`.', signature: '', constructors: [ApiConstructor(name: 'Oito2TimeEntry', doc: 'Creates a time entry.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'initialTime', type: 'TimeOfDay?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The time shown at start.'), ApiParameter(name: 'onChanged', type: 'ValueChanged<TimeOfDay?>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with each valid time, or null when the field is emptied.\n\nInvalid text doesn\'t call it, so the last valid time stays reported;\n[onErrorChanged] tells when the text doesn\'t parse.'), ApiParameter(name: 'onErrorChanged', type: 'ValueChanged<String?>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with the error message when the text stops being a valid\ntime, and with null when it is valid again.'), ApiParameter(name: 'labelText', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The field label; defaults to the localized "Enter time".'), ApiParameter(name: 'acceptEmpty', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether an empty field is valid.'), ApiParameter(name: 'autofocus', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether the field takes focus when shown.'), ApiParameter(name: 'focusNode', type: 'FocusNode?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The focus node; one is created when null.'), ApiParameter(name: 'showPickerButton', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether the clock picker button is shown.')])], properties: [], me