  'Oito2TimerController': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A stopwatch, or a countdown when [countdown] is set, that notifies its\nlisteners every [interval] while it runs.\n\nA countdown stops by itself at zero and calls [onComplete]. Time is\nmeasured from the clock [now], so it stays exact however late the ticks\narrive; the default clock is monotonic, unaffected by changes to the\nsystem time.', signature: '', constructors: [ApiConstructor(name: 'Oito2TimerController', doc: 'Creates a stopped timer at zero.\n\n[now] overrides the clock time is measured with, for example in tests.\nThrows an [AssertionError] in debug builds when [interval] is not\npositive.', isConst: false, isFactory: false, parameters: [ApiParameter(name: 'countdown', type: 'Duration?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The length of a countdown, or null for a stopwatch.'), ApiParameter(name: 'interval', type: 'Duration', isRequired: false, isNamed: true, defaultValue: 'const Duration(seconds: 1)', doc: 'How often listeners are notified while the timer runs.'), ApiParameter(name: 'onTick', type: 'ValueChanged<Duration>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with [elapsed] on every tick, including the final tick of a\ncountdown.'), ApiParameter(name: 'onComplete', type: 'VoidCallback?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called when a countdown reaches zero, after the listeners are\nnotified.'), ApiParameter(name: 'now', type: 'DateTime Function()?', isRequired: false, isNamed: true, defaultValue: '', doc: '')])], properties: [ApiMember(name: 'elapsed', signature: 'Duration', doc: 'The time run so far, up to [countdown].'), ApiMember(name: 'remaining', signature: 'Duration?', doc: 'The time left of a countdown, or null for a stopwatch.'), ApiMember(name: 'isRunning', signature: 'bool', doc: 'Whether the timer is running.'), ApiMember(name: 'isCompleted', signature: 'bool', doc: 'Whether a countdown has reached zero.')], methods: [ApiMember(name: 'start', signature: 'start() → void', doc: 'Starts or resumes the timer; does nothing while it runs, after a\ncountdown completes (see [restart]) or once disposed.'), ApiMember(name: 'pause', signature: 'pause() → void', doc: 'Pauses the timer, keeping the time run so far; does nothing when it\nisn\'t running or after [dispose].'), ApiMember(name: 'reset', signature: 'reset() → void', doc: 'Stops the timer and sets it back to zero, clearing [isCompleted];\ndoes nothing after [dispose].'), ApiMember(name: 'restart', signature: 'restart() → void', doc: 'Sets the timer back to zero and starts it.')], values: []),
  'Oito2TimerText': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'The time of an [Oito2TimerController] as text: the remaining time of a\ncountdown or the elapsed time of a stopwatch, in tabular figures so the\ndigits don\'t shift.', signature: '', constructors: [ApiConstructor(name: 'Oito2TimerText', doc: 'Creates a timer text.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'controller', type: 'Oito2TimerController', isRequired: true, isNamed: true, defaultValue: '', doc: 'The timer shown.'), ApiParameter(name: 'style', type: 'TextStyle?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The text style, merged over tabular figures.'), ApiParameter(name: 'tenths', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether tenths of a second show; without them a countdown rounds up\nto the whole second.')])], properties: [], methods: [], values: []),
  'Oito2TitleBar': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A desktop header bar: a title, optional leading widget and actions, and\nwindow control buttons in the order of [buttonLayout].\n\nThe empty area of the bar moves the window when dragged, maximizes or\nrestores it on double click and opens the window menu on secondary\nclick, through [controller]. Without a controller the buttons render\ndisabled, unless [onClose] handles the close button.\n\nMost apps use [Oito2WindowTitleBar], which picks the control style,\nlayout and controller from the system automatically.', signature: '', constructors: [ApiConstructor(name: 'Oito2TitleBar', doc: 'Creates a title bar.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'title', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The title, usually a [Text].'), ApiParameter(name: 'leading', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'A widget placed before the title, such as a back button.'), ApiParameter(name: 'actions', type: 'List<Widget>', isRequired: false, isNamed: true, defaultValue: 'const []', doc: 'Widgets placed after the title, such as icon buttons.'), ApiParameter(name: 'centerTitle', type: 'bool?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Whether the title is centered; defaults to the theme, then true.'), ApiParameter(name: 'style', type: 'Oito2TitleBarStyle?', isRequired: false, isNamed: true, defaultValue: '', doc: 'How the bar is presented; defaults to the theme, then\n[Oito2TitleBarStyle.normal].'), ApiParameter(name: 'controlStyle', type: 'Oito2WindowControlStyle', isRequired: false, isNamed: true, defaultValue: 'Oito2WindowControlStyle.gnome', doc: 'The visual family of the window control buttons.'), ApiParameter(name: 'buttonLayout', type: 'Oito2WindowButtonLayout', isRequired: false, isNamed: true, defaultValue: 'const Oito2WindowButtonLayout(trailing: [Oito2WindowButton.minimize, Oito2WindowButton.maxi