  'Oito2Toaster': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'Shows [Oito2Toast]s above [child], usually the whole app: wrap the\nnavigator in `MaterialApp.builder` with it, then call\n`Oito2Toaster.of(context).show(...)`.\n\nAt most [maxVisible] toasts show at a time, the oldest nearest the\n[placement] edge; newer ones wait for room. Each toast is announced\nto assistive technologies, closes on Escape while focused, and its\ntime stops while the pointer or the focus is on the stack.', signature: '', constructors: [ApiConstructor(name: 'Oito2Toaster', doc: 'Creates a toaster.\n\nThrows an [AssertionError] in debug builds when [maxVisible] is not\npositive.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'child', type: 'Widget', isRequired: true, isNamed: true, defaultValue: '', doc: 'The content below the toasts.'), ApiParameter(name: 'placement', type: 'Oito2ToasterPlacement', isRequired: false, isNamed: true, defaultValue: 'Oito2ToasterPlacement.bottom', doc: 'Where the toasts stack.'), ApiParameter(name: 'maxVisible', type: 'int', isRequired: false, isNamed: true, defaultValue: '3', doc: 'The largest number of toasts shown at a time.'), ApiParameter(name: 'maxWidth', type: 'double', isRequired: false, isNamed: true, defaultValue: '420', doc: 'The largest width of the toast stack, in logical pixels.')])], properties: [], methods: [ApiMember(name: 'of', signature: 'static of(BuildContext context) → Oito2ToasterState', doc: 'Returns the state of the closest [Oito2Toaster] above [context].\n\nThrows an [AssertionError] in debug builds, and a [TypeError] in\nrelease builds, when there is none; see [maybeOf].'), ApiMember(name: 'maybeOf', signature: 'static maybeOf(BuildContext context) → Oito2ToasterState?', doc: 'Returns the state of the closest [Oito2Toaster] above [context], or\nnull when there is none.')], values: []),
