  'Oito2ToggleGroup': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A joined row (or column) of buttons that turn on and off, such as text\nformatting or alignment buttons.\n\nWith [multiple], each item turns on and off by itself; otherwise turning\none on turns the others off, and [deselectable] says whether the one\nthat is on can be turned off. Items that are on are raised from the\ntrack.\n\nThe group is one stop in keyboard navigation: the arrow keys move\nbetween the enabled items, wrapping at the ends, and Space or Enter\ntoggles the focused one.', signature: '', constructors: [ApiConstructor(name: 'Oito2ToggleGroup', doc: 'Creates a toggle group.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'items', type: 'List<Oito2ToggleItem<T>>', isRequired: true, isNamed: true, defaultValue: '', doc: 'The items, in order.'), ApiParameter(name: 'selected', type: 'Set<T>', isRequired: true, isNamed: true, defaultValue: '', doc: 'The values of the items that are on.'), ApiParameter(name: 'onChanged', type: 'ValueChanged<Set<T>>?', isRequired: true, isNamed: true, defaultValue: '', doc: 'Called with the new set of values that are on; null disables the\ngroup.'), ApiParameter(name: 'multiple', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether several items can be on at once.'), ApiParameter(name: 'deselectable', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether the only item that is on can be turned off, leaving none on;\nignored when [multiple].'), ApiParameter(name: 'orientation', type: 'Axis', isRequired: false, isNamed: true, defaultValue: 'Axis.horizontal', doc: 'Whether the items run across or down.')])], properties: [], methods: [], values: []),
