  'Oito2Tour': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A guided tour over [child]: each step of the [controller] dims the\nwindow around its target, scrolls it into view and shows a card with\nthe step text, its position, and back, next and skip buttons.\n\nThe card takes the focus and is announced to assistive technologies;\nwhen the tour ends, the focus returns to where it was before. While the\ncard has focus, the arrow keys move between steps and Escape skips the\ntour. Taps outside the spotlight are blocked; taps inside reach the\ntarget, which moves a [Oito2TourStep.waitForTap] step on.', signature: '', constructors: [ApiConstructor(name: 'Oito2Tour', doc: 'Creates a tour.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'controller', type: 'Oito2TourController', isRequired: true, isNamed: true, defaultValue: '', doc: 'The steps and the current position.'), ApiParameter(name: 'child', type: 'Widget', isRequired: true, isNamed: true, defaultValue: '', doc: 'The content the tour runs over.'), ApiParameter(name: 'onFinished', type: 'ValueChanged<bool>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called when the tour ends, with true when it was completed and false\nwhen it was skipped.')])], properties: [], methods: [], values: []),
  'Oito2TourController': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'Runs an [Oito2Tour] through its [steps], notifying its listeners on\nevery step change and when the tour ends.', signature: '', constructors: [ApiConstructor(name: 'Oito2TourController', doc: 'Creates a tour controller that isn\'t running yet.\n\nThrows an [AssertionError] in debug builds when [steps] is empty.', isConst: false, isFactory: false, parameters: [ApiParameter(name: 'steps', type: 'List<Oito2TourStep>', isRequired: true, isNamed: true, defaultValue: '', doc: 'The steps, in order.')])], properties: [ApiMember(name: 'index', signature: 'int?', doc: 'The index of the current step, or null when the tour isn\'t running.'), ApiMember(name: 'step', signature: 'Oito2TourStep?', doc: 'The current step, or null when the tour isn\'t running.'), ApiMember(name: 'isActive', signature: 'bool', doc: 'Whether the tour is running.'), ApiMember(name: 'completed', signature: 'bool', doc: 'Whether the last run reached the end, rather than being skipped;\nfalse while a run is in progress.')], methods: [ApiMember(name: 'start', signature: 'start(int index) → void', doc: 'Starts the tour, or restarts it, at the step at [index].\n\nThrows an [AssertionError] in debug builds when [index] is out of\nrange.'), ApiMember(name: 'goTo', signature: 'goTo(int index) → void', doc: 'Shows the step at [index], starting the tour when it isn\'t running.\n\nThrows an [AssertionError] in debug builds when [index] is out of\nrange.'), ApiMember(name: 'next', signature: 'next() → void', doc: 'Moves to the next step, or completes the tour after the last; does\nnothing when the tour isn\'t running.'), ApiMember(name: 'previous', signature: 'previous() → void', doc: 'Moves to the previous step; does nothing on the first step or when\nthe tour isn\'t running.'), ApiMember(name: 'skip', signature: 'skip() → void', doc: 'Ends the tour without completing it; does nothing when it isn\'t\nrunning.')], values: []),
