  'Oito2TreeCollection': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'An immutable tree of [Oito2TreeNode]s with the queries a tree view\nneeds: lookups by value and index path, parents and siblings, the\nvisible order for a set of expanded branches, filtering and copies with\nnodes inserted, removed, moved or replaced.\n\nAn index path lists the child indexes from the top level down, such as\n`[0, 2]` for the third child of the first top-level node.', signature: '', constructors: [ApiConstructor(name: 'Oito2TreeCollection', doc: 'Creates a tree with the top-level [roots].\n\nThrows an [ArgumentError] when two nodes share a value.', isConst: false, isFactory: false, parameters: [ApiParameter(name: 'roots', type: 'Iterable<Oito2TreeNode<T>>', isRequired: true, isNamed: false, defaultValue: '', doc: '')]), ApiConstructor(name: 'Oito2TreeCollection.fromPaths', doc: 'Builds a tree from [paths] split by [separator], such as file paths:\neach segment becomes a branch and the last one a leaf, unless another\npath continues below it. Empty segments are skipped. Node values are\nthe paths up to each node, joined by [separator], and labels are the\nsegment names.', isConst: false, isFactory: true, parameters: [ApiParameter(name: 'paths', type: 'Iterable<String>', isRequired: true, isNamed: false, defaultValue: '', doc: ''), ApiParameter(name: 'separator', type: 'String', isRequired: false, isNamed: true, defaultValue: '\'/\'', doc: '')])], properties: [ApiMember(name: 'values', signature: 'List<String>', doc: 'The values of every node, in depth-first order.'), ApiMember(name: 'branchValues', signature: 'List<String>', doc: 'The values of every branch.')], methods: [ApiMember(name: 'has', signature: 'has(String? value) → bool', doc: 'Whether a node has [value].'), ApiMember(name: 'indexPathOf', signature: 'indexPathOf(String value) → List<int>?', doc: 'Returns the index path of the node with [value], or null when there is\nnone.'), ApiMember(name: 'nodeAt', signature: 'nodeAt(List<int> indexPath) → Oito2TreeNode<T>?', doc: 'Returns the node at [indexPath], or null when the path is empty or\ndoesn\'t exist.'), ApiMember(name: 'find', signature: 'find(String? value) → Oito2TreeNode<T>?', doc: 'Returns the node with [value], or null when there is none.'), ApiMember(name: 'parentOf', signature: 'parentOf(String value) → String?', doc: 'Returns the value of the parent of [value], or null for a top-level\nor unknown node.'), ApiMember(name: 'childrenOf', signature: 'childrenOf(String value) → List<Oito2TreeNode<T>>', doc: 'Returns the children of [value]; empty for a leaf or a missing node.'), ApiMember(name: 'siblingsOf', signature: 'siblingsOf(String value) → List<Oito2TreeNode<T>>', doc: 'Returns the nodes that share a parent with [value], including it; the\ntop-level nodes for an unknown value.'), ApiMember(name: 'ancestorsOf', signature: 'ancestorsOf(String value) → List<String>', doc: 'Returns the values of the ancestors of [value], from the top level\ndown.'), ApiMember(name: 'depthOf', signature: 'depthOf(String value) → int', doc: 'Returns the depth of [value]: 0 at the top level, and also 0 for an\nunknown value.'), ApiMember(name: 'flatten', signature: 'flatten() → List<({int depth, List<int> indexPath, Oito2TreeNode<T> node})>', doc: 'Returns every node in depth-first order with its depth and index\npath.'), ApiMember(name: 'visible', signature: 'visible(Set<String> expanded) → List<({int depth, List<int> indexPath, Oito2TreeNode<T> node})>', doc: 'Returns the nodes a tree view shows when the branches in [expanded]\nare open, in display order.'), ApiMember(name: 'descendantsOf', signature: 'descendantsOf(String value) → List<String>', doc: 'Returns the values of every node below [value], in depth-first order.'), ApiMember(name: 'leavesOf', signature: 'leavesOf(String value) → List<String>', doc: 'Returns the values of the leaves below [value], or [value] itself when\nit is a leaf; empty for an unknown value. Empty branches do