  'Oito2VerticalTabBar': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'A column of tabs with a rounded marker that slides to the selected one,\nfor side navigation between views of the same content.\n\nIt drives a [TabController] like [Oito2TabBar]: the [controller] given,\nor the closest `DefaultTabController`; [style] picks the marker look.\nThe tabs take the full width and line up at the leading edge. The\nselected tab is the bar\'s one stop in keyboard navigation, and the up\nand down arrows, Home and End move the selection. Throws a\n[FlutterError] in debug builds when neither [controller] nor a\n`DefaultTabController` is available.', signature: '', constructors: [ApiConstructor(name: 'Oito2VerticalTabBar', doc: 'Creates a vertical tab bar.\n\nThrows an [AssertionError] in debug builds when the controller\'s\nlength differs from the number of [tabs].', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'tabs', type: 'List<Widget>', isRequired: true, isNamed: true, defaultValue: '', doc: 'The tabs, usually [Oito2Tab]s.'), ApiParameter(name: 'controller', type: 'TabController?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The tab controller; defaults to the closest `DefaultTabController`.'), ApiParameter(name: 'onTap', type: 'ValueChanged<int>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called with the index of a tab selected by a tap or a key.'), ApiParameter(name: 'style', type: 'Oito2TabBarStyle', isRequired: false, isNamed: true, defaultValue: 'Oito2TabBarStyle.pill', doc: 'The look of the selected tab marker.')])], properties: [], methods: [], values: []),
