  'Oito2WindowTitleBar': ApiEntry(kind: 'class', package: 'oito2_ui', doc: 'The app window\'s title bar, adapted to the platform.\n\n- On native Linux and Windows it is an [Oito2TitleBar] with the window\n  control style and button layout of [Oito2SystemScope], driven by the\n  [Oito2WindowScope] controller.\n- On native macOS it keeps room for the native traffic lights instead\n  of drawing its own buttons.\n- On the web it shows the title and actions without window buttons,\n  since the browser owns the page lifecycle.\n- On touch platforms it is a regular [AppBar], which handles the\n  status bar safe area.', signature: '', constructors: [ApiConstructor(name: 'Oito2WindowTitleBar', doc: 'Creates an adaptive window title bar.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'title', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The title, usually a [Text].'), ApiParameter(name: 'leading', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'A widget placed before the title.'), ApiParameter(name: 'actions', type: 'List<Widget>', isRequired: false, isNamed: true, defaultValue: 'const []', doc: 'Widgets placed after the title.'), ApiParameter(name: 'centerTitle', type: 'bool?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Whether the title is centered; defaults to the theme.'), ApiParameter(name: 'style', type: 'Oito2TitleBarStyle?', isRequired: false, isNamed: true, defaultValue: '', doc: 'How the bar is presented on desktop platforms; defaults to the theme.'), ApiParameter(name: 'controller', type: 'Oito2WindowController?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The window controller; defaults to the closest [Oito2WindowScope].'), ApiParameter(name: 'labels', type: 'Oito2WindowControlLabels?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Overrides of the window buttons\' accessibility labels, which\notherwise come from [Oito2Localizations].'), ApiParame