  'oito2PaginationItems': ApiEntry(kind: 'function', package: 'oito2_ui', doc: 'The page numbers a pagination shows for [page] of [count], with null\nfor an ellipsis.\n\nIt keeps [boundaryCount] pages at each end and [siblingCount] pages on\neach side of [page], and always returns the same number of items for a\ngiven [count], so the buttons don\'t shift as the page changes. An\nellipsis never stands for a single page. Pages count from 1, and a\n[count] of zero or less gives an empty list.\n\nThrows an [AssertionError] in debug mode when [siblingCount] or\n[boundaryCount] is negative.', signature: 'oito2PaginationItems(int page, int count, int siblingCount, int boundaryCount) → List<int?>', constructors: [], properties: [], methods: [], values: []),
  'oito2UsesCommandKey': ApiEntry(kind: 'function', package: 'oito2_ui', doc: 'Whether [platform] uses Command, rather than Control, as the primary\nshortcut modifier: macOS and iOS.', signature: 'oito2UsesCommandKey(TargetPlatform platform) → bool', constructors: [], properties: [], methods: [], values: []),
  'showOito2CommandPalette': ApiEntry(kind: 'function', package: 'oito2_ui', doc: 'Opens the command palette over [context]: a search field above the\ncommands available at [context] (or [commands] when given), each with\nits shortcut.\n\nTyping filters the commands to those whose label, description, group\nand keywords contain every typed word, ignoring case and accents.\nCommands whose label starts with the first word come first, then those\nwhose label contains every word. The arrow keys move the highlight,\nEnter or a click closes the palette and runs a command, and Escape\ncloses it.', signature: 'showOito2CommandPalette(BuildContext context, List<Oito2Command>? commands) → Future<void>', constructors: [], properties: [], methods: [], values: []),
  'showOito2Sheet': ApiEntry(kind: 'function', package: 'oito2_ui', doc: 'Shows a sheet built by [builder] sliding in from [side], usually with\nan [Oito2Sheet] as its content, and completes with the value it is\nclosed with.\n\nA [modal] sheet dims the page and keeps the focus and assistive\ntechnologies inside it; a tap on the dimmed page closes it when\n[dismissible]. A non-modal sheet leaves the page usable beside it.\nEither closes on Escape and, when [dismissible], when dragged toward\nits edge.\n\nA side sheet is [size] wide (360 by default). A bottom sheet is as\ntall as its content, up to 90% of the window, unless [snapPoints]\ngives the heights it rests at as fractions of the window height,\nascending, starting at the [initialSnap] index; its handle then moves\nbetween them by drag, by the arrow keys, or by a tap, Enter or Space,\nwhich cycle to the next height.\n\nThrows an [AssertionError] in debug mode when [snapPoints] is given for\na side sheet, or when it is empty or [initialSnap] does not index it.', signature: 'showOito2Sheet(BuildContext context, WidgetBuilder builder, Oito2SheetSide side, bool modal, bool dismissible, double? size, List<double>? snapPoints, int initialSnap, String? semanticLabel) → Future<T?>', constructors: [], properties: [], methods: [], values: []),
  'Oito2NativeWindowController': ApiEntry(kind: 'class', package: 'oito2_ui_window', doc: 'An [Oito2WindowController] backed by `window_manager`.\n\nForwards the window actions to a [WindowManager] and keeps [state] in\nsync with its maximize, focus and full-screen events.', signature: '', constructors: [], properties: [], methods: [ApiMember(name: 'attach', signature: 'static attach(WindowManager manager, bool canShowMenu) → Future<Oito2NativeWindowController>', doc: 'Creates a controller for [manager], reads the current window state and\nstarts listening to window events.\n\n[canShowMenu] tells whether the platform supports the native window\nmenu.'), ApiMember(name: 'refresh', signature: 'refresh() → Future<void>', doc: 'Reads the maximized, full-screen and focus state from the window.\n\nThe last known state stays when the window can\'t be queried, when a\nwindow event arrives meanwhile, or after [dispose].'), ApiMember(name: 'dispose', signature: 'dispose() → void', doc: 'Stops listening to window events and releases [state].')], values: []),
  'Oito2Window': ApiEntry(kind: 'abstract class', package: 'oito2_ui_window', doc: 'Entry point for native window integration.', signature: '', constructors: [ApiConstructor(name: 'Oito2Window', doc: '', isConst: false, isFactory: false, parameters: [])], properties: [], methods: [ApiMember(name: 'ensureInitialized', signature: 'static ensureInitialized(String? title, Size? size, Size? minimumSize, bool center) → Future<Oito2WindowController?>', doc: 'Hides the native title bar, applies the initial window options, shows\nthe window and returns an [Oito2WindowController] for it.\n\n[title] sets the window title, [size] the initial size and\n[minimumSize] the smallest size the user can resize it to; when\n[center] is true the window opens centered on the screen.\n\nCall it in `main` before `runApp`, and provide the result through an\n[Oito2WindowScope]. Returns null on the web, Android and iOS, where\nthe app doesn\'t own a desktop window, and when the window plugin\nisn\'t available; `Oito2WindowTitleBar` then adapts on its own. On\ndesktop the controller is an [Oito2NativeWindowController], which the\napp can dispose when it no longer needs it.\n\nOn macOS the native traffic lights stay visible over the hidden\ntitle bar.')], values: []),
  'Oito2AccentSource': ApiEntry(kind: 'abstract class', package: 'oito2_ui_settings', doc: 'Reads the accent color the operating system or the toolkit theme\nexposes.', signature: '', constructors: [ApiConstructor(name: 'Oito2AccentSource', doc: '', isConst: false, isFactory: false, parameters: [])], properties: [], methods: [ApiMember(name: 'read', signature: 'read() → Future<Color?>', doc: 'Returns the accent color, or null when none is available.'), ApiMember(name: 'changes', signature: 'changes() → Stream<void>', doc: 'Emits whenever the accent color changes.')], values: []),
  'Oito2ConfigFileSource': ApiEntry(kind: 'abstract class', package: 'oito2_ui_settings', doc: 'Reads text files from the user\'s configuration directory\n(`\$XDG_CONFIG_HOME`, by default `~/.config`).', signature: '', constructors: [ApiConstructor(name: 'Oito2ConfigFileSource', doc: '', isConst: false, isFactory: false, parameters: [])], properties: [], methods: [ApiMember(name: 'read', signature: 'read(String relativePath) → Future<String?>', doc: 'Returns the content of the file at [relativePath], or null when it\ndoesn\'t exist or can\'t be read.'), ApiMember(name: 'changes', signature: 'changes(String relativePath) → Stream<void>', doc: 'Emits whenever the file at [relativePath] changes.')], values: []),
  'Oito2ConfigParsers': ApiEntry(kind: 'abstract class', package: 'oito2_ui_settings', doc: 'Parsers for the configuration file formats of Linux desktops.', signature: '', constructors: [ApiConstructor(name: 'Oito2ConfigParsers', doc: '', isConst: false, isFactory: false, parameters: [])], properties: [], methods: [ApiMember(name: 'iniValue', signature: 'static iniValue(String content, String group, String key) → String?', doc: 'Returns the value of [key] in [group] of the INI-style [content], such\nas KDE\'s `kwinrc` and `kdeglobals`, or null when it is missing.\n\nGroup headers are `[name]`; nested KDE groups like `[a][b]` match the\nname `a][b`. Lines starting with `#` or `;` are comments. Keys with\na locale or KDE flag suffix (`key[\$e]`) are ignored.'), ApiMember(name: 'xfconfProperty', signature: 'static xfconfProperty(String content, String name) → String?', doc: 'Returns the `value` attribute of the `<property name="[name]">`\nelement in the xfconf channel file [content], such as `xfwm4.xml`, or\nnull when it is missing. XML entities in the value are decoded.'), ApiMember(name: 'cosmicBool', signature: 'static cosmicBool(String content) → bool?', doc: 'Parses [content] as a `true`/`false` file, as COSMIC stores its\nboolean settings.\n\nReturns null for any other content.'), ApiMember(name: 'kdeColor', signature: 'static kdeColor(String value) → Color?', doc: 'Parses [value] as a KDE `r,g,b` color, such as the value of\n`AccentColor=61,174,233`, or returns null when it isn\'t one with\nthree components from 0 to 255.')], values: []),
  'Oito2EmptySource': ApiEntry(kind: 'class', package: 'oito2_ui_settings', doc: 'A source with no values and no changes, used where a platform has no\nsuch store.', signature: '', constructors: [ApiConstructor(name: 'Oito2EmptySource', doc: 'Creates an empty source.', isConst: true, isFactory: false, parameters: [])], properties: [], methods: [], values: []),
  'Oito2GSettingsSource': ApiEntry(kind: 'abstract class', package: 'oito2_ui_settings', doc: 'Reads values from GSettings, the settings store of GNOME and the\ndesktops derived from it.', signature: '', constructors: [ApiConstructor(name: 'Oito2GSettingsSource', doc: '', isConst: false, isFactory: false, parameters: [])], properties: [], methods: [ApiMember(name: 'read', signature: 'read(String schema, String key) → Future<Object?>', doc: 'Returns the value of [key] in [schema] as a Dart value (`String`,\n`bool`, `int`, ...), or null when the schema or key doesn\'t exist.'), ApiMember(name: 'changes', signature: 'changes(String schema) → Stream<void>', doc: 'Emits whenever a key in [schema] changes.'), ApiMember(name: 'close', signature: 'close() → Future<void>', doc: 'Releases the connections the source holds.')], values: []),
  'Oito2Settings': ApiEntry(kind: 'abstract class', package: 'oito2_ui_settings', doc: 'Entry point for reading the operating system preferences.', signature: '', constructors: [ApiConstructor(name: 'Oito2Settings', doc: '', isConst: false, isFactory: false, parameters: [])], properties: [], methods: [ApiMember(name: 'reader', signature: 'static reader(Oito2Platform? platform) → Oito2SystemSettingsReader', doc: 'Creates the reader for [platform] (default [Oito2Platform.current])\nbacked by the real system stores.'), ApiMember(name: 'load', signature: 'static load(Oito2Platform? platform) → Future<Oito2SystemSettings>', doc: 'Reads the current system settings of [platform] once, then releases\nthe reader.'), ApiMember(name: 'watch', signature: 'static watch(Oito2Platform? platform) → Stream<Oito2SystemSettings>', doc: 'Emits the current system settings of [platform], then every change.\n\nThe reader, with its system connections, is created when the stream\nis listened to and released when the subscription is cancelled, so a\nstream that is never listened to opens nothing.')], values: []),
  'Oito2SystemSettingsReader': ApiEntry(kind: 'class', package: 'oito2_ui_settings', doc: 'Builds [Oito2SystemSettings] from the system stores of the current\nplatform.\n\nOn native Linux it detects the desktop environment from [environment]\nand reads the window button layout per desktop:\n\n- GNOME, Budgie, Pantheon, Unity and unknown desktops:\n  `org.gnome.desktop.wm.preferences button-layout`.\n- Cinnamon: `org.cinnamon.desktop.wm.preferences button-layout`.\n- MATE: `org.mate.Marco.general button-layout`.\n- KDE Plasma: `ButtonsOnLeft` and `ButtonsOnRight` in the\n  `[org.kde.kdecoration2]` group of `kwinrc`.\n- Xfce: `button_layout` in `xfwm4.xml`.\n- COSMIC: `com.system76.CosmicTk/v1/show_minimize` and\n  `show_maximize`.\n\nKDE Plasma reads the accent from `AccentColor` in the `[General]` group\nof `kdeglobals`, and high contrast from a `kdeglobals` color scheme whose\nname contains "contrast". Every other desktop reads the accent from\n`org.gnome.desktop.interface accent-color`, and high contrast from\n`org.gnome.desktop.a11y.interface high-contrast` or a `HighContrast` GTK\ntheme. Without a desktop accent, the accent comes from the toolkit\ntheme through [accent].\n\nMissing values fall back to each desktop\'s defaults. On other\nplatforms only the accent comes from [accent]. [platformHighContrast]\nis combined with the desktop preference on every platform.', signature: '', constructors: [ApiConstructor(name: 'Oito2SystemSettingsReader', doc: 'Creates a reader for [platform] over the given sources.\n\nEvery source defaults to an [Oito2EmptySource], and\n[platformHighContrast] to a function that returns false.', isConst: false, isFactory: false, parameters: [ApiParameter(name: 'platform', type: 'Oito2Platform', isRequired: true, isNamed: true, defaultValue: '', doc: 'The platform the settings are read for.'), ApiParameter(name: 'environment', type: 'Map<String, String>', isRequired: false, isNamed: true, defaultValue: 'const {}', doc: 'The process environment variables.'), ApiParameter(name: 'gsettings', type: 'Oito2GSettingsSource', isRequired: false, isNamed: true, defaultValue: 'const Oito2EmptySource()', doc: 'The GSettings store.'), ApiParameter(name: 'configFiles', type: 'Oito2ConfigFileSource', isRequired: false, isNamed: true, defaultValue: 'const Oito2EmptySource()', doc: 'The user\'s configuration files.'), ApiParameter(name: 'accent', type: 'Oito2AccentSource', isRequired: false, isNamed: true, defaultValue: 'const Oito2EmptySource()', doc: 'The toolkit or operating system accent color.'), ApiParameter(name: 'platformHighContrast', type: 'bool Function()', isRequired: false, isNamed: true, defaultValue: '', doc: 'Whether the platform accessibility settings ask for high contrast.'), ApiParameter(name: 'debounce', type: 'Duration', isRequired: false, isNamed: true, defaultValue: 'const Duration(milliseconds: 150)', doc: 'How long [watch] waits after a change before reading again, so a\nburst of changes produces one update.')])], properties: [ApiMember(name: 'desktopEnvironment', signature: 'Oito2DesktopEnvironment?', doc: 'The detected desktop environment, or null outside native Linux.')], methods: [ApiMember(name: 'read', signature: 'read() → Future<Oito2SystemSettings>', doc: 'Reads the current settings from every source.\n\nA source that fails to read counts as missing, so its value falls\nback to the desktop default.'), ApiMember(name: 'watch', signature: 'watch() → Stream<Oito2SystemSettings>', doc: 'Emits the current settings, then the new settings whenever a source\nreports a change that alters them.\n\nA read that a newer one overtakes is dropped, and a failed read is\nemitted as an error.'), ApiMember(name: 'close', signature: 'close() → Future<void>', doc: 'Releases the connections the system stores hold, such as the D-Bus\nconnections of GSettings. The reader can\'t be used afterwards.')], values: []),
  'Oito2SystemSettingsScope': ApiEntry(kind: 'class', package: 'oito2_ui_settings', doc: 'Keeps an [Oito2SystemScope] in sync with the operating system.\n\nShows [initialSettings] (or the platform fallback) until the first read\ncompletes, then rebuilds [child] whenever the desktop environment\nsettings, the accent color or the accessibility preferences change.', signature: '', constructors: [ApiConstructor(name: 'Oito2SystemSettingsScope', doc: 'Creates a scope that watches the system settings for [child].', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'initialSettings', type: 'Oito2SystemSettings?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The settings shown before the first read, typically the result of\n[Oito2Settings.load] awaited in `main`.'), ApiParameter(name: 'reader', type: 'Oito2SystemSettingsReader?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The reader to watch; defaults to [Oito2Settings.reader].'), ApiParameter(name: 'child', type: 'Widget', isRequired: true, isNamed: true, defaultValue: '', doc: 'The widget below the scope.')])], properties: [], methods: [], values: []),
  'Oito2CodeBlock': ApiEntry(kind: 'class', package: 'oito2_ui_syntax', doc: 'A read-only, selectable block of highlighted code on the theme\'s\ncontainer surface, with optional line numbers and a copy button.\n\nThe colors come from the theme\'s [Oito2SyntaxTheme], or from the oito2\nbase scheme of the current brightness when the theme has none. Long\nlines scroll horizontally instead of wrapping.', signature: '', constructors: [ApiConstructor(name: 'Oito2CodeBlock', doc: 'Creates a code block.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'code', type: 'String', isRequired: true, isNamed: true, defaultValue: '', doc: 'The source code.'), ApiParameter(name: 'language', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The language name or alias, such as `dart`; null or an unregistered\nname shows plain text.'), ApiParameter(name: 'highlighter', type: 'Oito2Highlighter?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The highlighter; defaults to [Oito2Highlighter.instance].'), ApiParameter(name: 'showLineNumbers', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether line numbers are shown.'), ApiParameter(name: 'showCopyButton', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether the copy button is shown.'), ApiParameter(name: 'textStyle', type: 'TextStyle?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The code text style; defaults to [Oito2CodeBlock.defaultTextStyle].'), ApiParameter(name: 'padding', type: 'EdgeInsetsGeometry', isRequired: false, isNamed: true, defaultValue: 'const EdgeInsets.all(Oito2Spacing.lg)', doc: 'Space around the code.')])], properties: [ApiMember(name: 'fontFamily', signature: 'static String', doc: 'The family name of JetBrains Mono as bundled by this package,\nincluding the package prefix.'), ApiMember(name: 'monospaceFallback', signature: 'static List<String>', doc: 'System monospace families used for glyphs the bundled font lacks, in\norder.'), ApiMember(name: 'defaultTextStyle', signature: 'static TextStyle', doc: 'The default code text style: 13-point bundled JetBrains Mono with\n1.45 line height.')], methods: [], values: []),
  'Oito2Highlighter': ApiEntry(kind: 'class', package: 'oito2_ui_syntax', doc: 'Turns source code into a [TextSpan] colored with a\n[Oito2SyntaxPalette].\n\nTokenizing runs synchronously in pure Dart, with no native code and no\nasset loading.', signature: '', constructors: [ApiConstructor(name: 'Oito2Highlighter', doc: 'Creates a highlighter that knows [languages] (by default\n[oito2DefaultLanguages]).', isConst: false, isFactory: false, parameters: [ApiParameter(name: 'languages', type: 'Map<String, Mode>?', isRequired: false, isNamed: true, defaultValue: '', doc: '')])], properties: [ApiMember(name: 'instance', signature: 'static Oito2Highlighter', doc: 'A shared highlighter with the default languages.')], methods: [ApiMember(name: 'supports', signature: 'supports(String language) → bool', doc: 'Whether [language] is registered, by name or by one of its aliases\n(such as `js` or `yml`), in any letter case.'), ApiMember(name: 'highlight', signature: 'highlight(String code, Oito2SyntaxPalette palette, String? language, TextStyle? style, bool autoDetect) → TextSpan', doc: 'Returns [code] highlighted as [language] with [palette], on top of\n[style] (whose color is replaced by the palette foreground).\n\n[language] is a registered name or alias, in any letter case. When it\nisn\'t registered, or is null and [autoDetect] is false, the code is\nreturned unhighlighted in the foreground color. With [autoDetect], a\nnull [language] is guessed among the registered ones.')], values: []),
  'Oito2HighlighterTheme': ApiEntry(kind: 'abstract class', package: 'oito2_ui_syntax', doc: 'Builds `re_highlight` themes from a [Oito2SyntaxPalette].\n\nThe highlighter tokenizes code with highlight.js grammars, whose token\nscopes (such as `keyword`, `title.function` or `selector-tag`) are\nmapped here to the 11 palette roles. Scopes not listed render in the\nforeground color.', signature: '', constructors: [ApiConstructor(name: 'Oito2HighlighterTheme', doc: '', isConst: false, isFactory: false, parameters: [])], properties: [ApiMember(name: 'scopeRoles', signature: 'static Map<String, Oito2SyntaxRole>', doc: 'The palette role of every highlight.js scope the theme colors.')], methods: [ApiMember(name: 'fromPalette', signature: 'static fromPalette(Oito2SyntaxPalette palette) → Map<String, TextStyle>', doc: 'Returns the scope styles for [palette]: every scope of [scopeRoles]\nin its role color, comments in italics, plus italic `emphasis` and\nbold `strong` for markup.')], values: []),
  'Oito2SyntaxRole': ApiEntry(kind: 'enum', package: 'oito2_ui_syntax', doc: 'A token role of a [Oito2SyntaxPalette].', signature: '', constructors: [], properties: [], methods: [ApiMember(name: 'colorIn', signature: 'colorIn(Oito2SyntaxPalette palette) → Color', doc: 'The color of this role in [palette].')], values: [ApiMember(name: 'foreground', signature: '', doc: 'Plain code text.'), ApiMember(name: 'comment', signature: '', doc: 'Comments.'), ApiMember(name: 'keyword', signature: '', doc: 'Keywords and control flow.'), ApiMember(name: 'string', signature: '', doc: 'String literals.'), ApiMember(name: 'number', signature: '', doc: 'Numeric literals.'), ApiMember(name: 'function', signature: '', doc: 'Function and method names.'), ApiMember(name: 'type', signature: '', doc: 'Type and class names.'), ApiMember(name: 'tag', signature: '', doc: 'Markup tags.'), ApiMember(name: 'attribute', signature: '', doc: 'Markup attributes, annotations and properties.'), ApiMember(name: 'constant', signature: '', doc: 'Constants, booleans and enum values.'), ApiMember(name: 'invalid', signature: '', doc: 'Invalid code and removed lines.')]),
