  'Oito2DraculaPalette': ApiEntry(kind: 'class', package: 'oito2_ui_themes', doc: 'The official Dracula palette and its light variant, Alucard.', signature: '', constructors: [ApiConstructor(name: 'Oito2DraculaPalette', doc: 'Creates a Dracula-family palette from explicit colors.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'background', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: 'Background.'), ApiParameter(name: 'currentLine', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: 'Current line highlight.'), ApiParameter(name: 'foreground', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: 'Foreground text.'), ApiParameter(name: 'comment', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: 'Comments.'), ApiParameter(name: 'cyan', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: 'Cyan.'), ApiParameter(name: 'green', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: 'Green.'), ApiParameter(name: 'orange', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: 'Orange.'), ApiParameter(name: 'pink', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: 'Pink.'), ApiParameter(name: 'purple', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: 'Purple.'), ApiParameter(name: 'red', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: 'Red.'), ApiParameter(name: 'yellow', type: 'Color', isRequired: true, isNamed: true, defaultValue: '', doc: 'Yellow.')])], properties: [ApiMember(name: 'dracula', signature: 'static Oito2DraculaPalette', doc: 'Dracula, the dark variant.'), ApiMember(name: 'alucard', signature: 'static Oito2DraculaPalette', doc: 'Alucard, the light variant.')], methods: [], values: []),
