  'Oito2CropController': ApiEntry(kind: 'class', package: 'oito2_ui_extras', doc: 'The zoom, pan, rotation and flip of an [Oito2ImageCropper], and the\ncrop itself.\n\nThe pan is in the crop box\'s logical pixels and is kept so the image\nalways covers the box.', signature: '', constructors: [ApiConstructor(name: 'Oito2CropController', doc: 'Creates a crop controller that zooms up to [maxZoom].\n\nAsserts that [maxZoom] is at least 1.', isConst: false, isFactory: false, parameters: [ApiParameter(name: 'maxZoom', type: 'double', isRequired: false, isNamed: true, defaultValue: '5', doc: 'The largest zoom, as a multiple of the zoom that just covers the box.')])], properties: [ApiMember(name: 'image', signature: 'Image?', doc: 'The loaded image, or null while it loads.'), ApiMember(name: 'zoom', signature: 'double', doc: 'The zoom, from 1 (the image just covers the box) to [maxZoom].'), ApiMember(name: 'offset', signature: 'Offset', doc: 'The pan of the image center from the box center.'), ApiMember(name: 'quarterTurns', signature: 'int', doc: 'The clockwise quarter turns applied to the image before the flip,\nfrom 0 to 3.'), ApiMember(name: 'flipped', signature: 'bool', doc: 'Whether the image is mirrored horizontally.'), ApiMember(name: 'boxSize', signature: 'Size', doc: 'The crop box size in logical pixels, set by the cropper\'s layout.')], methods: [ApiMember(name: 'zoomBy', signature: 'zoomBy(double factor) → void', doc: 'Multiplies the zoom by [factor].'), ApiMember(name: 'panBy', signature: 'panBy(Offset delta) → void', doc: 'Moves the image by [delta], as far as the image still covers the box.'), ApiMember(name: 'rotateRight', signature: 'rotateRight() → void', doc: 'Turns the image a quarter clockwise on screen.'), ApiMember(name: 'rotateLeft', signature: 'rotateLeft() → void', doc: 'Turns the image a quarter counterclockwise on screen.'), ApiMember(name: 'flipHorizontally', signature: 'flipHorizontally() → void', doc: 'Mirrors the image horizontally.'), ApiMember(name: 'reset', signature: 'reset() → void', doc: 'Restores the zoom, pan, rotation and flip.'), ApiMember(name: 'paintCrop', signature: 'paintCrop(Canvas canvas) → void', doc: 'Paints the image as it shows in a crop box of [boxSize] at the\ncanvas origin.'), ApiMember(name: 'crop', signature: 'crop(double? width, bool circle) → Future<Image?>', doc: 'Returns the cropped image at the decoded image\'s resolution, or\n[width] pixels wide when given, cut to a circle when [circle] is set.\n\nReturns null before the image loads or before the box is laid out.\nThe caller owns the returned image and must dispose it.')], values: []),
  'Oito2CropPreview': ApiEntry(kind: 'class', package: 'oito2_ui_extras', doc: 'The current crop of an [Oito2CropController] at [width], updated as\nthe user zooms, pans, rotates and flips.', signature: '', constructors: [ApiConstructor(name: 'Oito2CropPreview', doc: 'Creates a crop preview.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'controller', type: 'Oito2CropController', isRequired: true, isNamed: true, defaultValue: '', doc: 'The controller whose crop is shown.'), ApiParameter(name: 'width', type: 'double', isRequired: false, isNamed: true, defaultValue: '96', doc: 'The preview width; the height follows the crop box.'), ApiParameter(name: 'circle', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether the preview is cut to a circle.')])], properties: [], methods: [], values: []),
  'Oito2ImageCropper': ApiEntry(kind: 'class', package: 'oito2_ui_extras', doc: 'Crops [image]: the user zooms and pans it under a crop box of\n[aspectRatio], rotates it by quarter turns and flips it, and the app\nreads the result from [controller].\n\nThe image moves by dragging and zooms by pinching, the mouse wheel or\nthe toolbar. With the focus on the crop area the arrow keys pan (more\nwith Shift), plus and minus zoom, R rotates (Shift+R the other way)\nand H flips. With [circle] the box is a circle. [Oito2CropPreview]\nshows the result live.', signature: '', constructors: [ApiConstructor(name: 'Oito2ImageCropper', doc: 'Creates an image cropper.\n\nAsserts that [aspectRatio] is positive and that\n[maxDecodedDimension], when given, is positive.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'image', type: 'ImageProvider<Object>', isRequired: true, isNamed: true, defaultValue: '', doc: 'The image to crop.'), ApiParameter(name: 'controller', type: 'Oito2CropController', isRequired: true, isNamed: true, defaultValue: '', doc: 'The controller that holds the zoom, pan, rotation and flip.'), ApiParameter(name: 'aspectRatio', type: 'double', isRequired: false, isNamed: true, defaultValue: '1', doc: 'The crop box width divided by its height; ignored with [circle],\nwhich uses 1.'), ApiParameter(name: 'circle', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether the crop box is a circle.'), ApiParameter(name: 'height', type: 'double', isRequired: false, isNamed: true, defaultValue: '320', doc: 'The height of the crop area.'), ApiParameter(name: 'showToolbar', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether the zoom, rotate, flip and reset controls show.'), ApiParameter(name: 'semanticLabel', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The accessibility label; defaults to the localized "Image cropper".'), ApiParameter(name: 'maxDecodedDimension', type: 'int?', isRequired: false, isNamed: true, defaultValue: '4096', doc: 'The longest side, in pixels, the image is decoded at; larger images\nare scaled down while decoding, keeping their aspect ratio, to bound\nthe memory they take. Null decodes at full size.'), ApiParameter(name: 'onError', type: 'void Function(Object, StackTrace?)?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called when the image fails to load; without it the error is\nreported through [FlutterError.reportError].')])], properties: [], methods: [], values: []),
  'Oito2NavigationMenu': ApiEntry(kind: 'class', package: 'oito2_ui_extras', doc: 'A website-style header menu: links and triggers in a row, a line that\nslides under the [selectedIndex] item, and flyout panels below the\ntriggers.\n\nA panel opens on hover after [hoverDelay], or when its trigger is\npressed or gets Down, which also move the focus into it; moving the\npointer to another trigger switches panels at once. Tab moves the focus\nbetween the items and Escape closes a panel.', signature: '', constructors: [ApiConstructor(name: 'Oito2NavigationMenu', doc: 'Creates a navigation menu.\n\nAsserts that [selectedIndex], when given, is not negative.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'items', type: 'List<Oito2NavigationMenuItem>', isRequired: true, isNamed: true, defaultValue: '', doc: 'The items, in order.'), ApiParameter(name: 'selectedIndex', type: 'int?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The index of the item that marks the current page, or null for none.'), ApiParameter(name: 'hoverDelay', type: 'Duration', isRequired: false, isNamed: true, defaultValue: 'const Duration(milliseconds: 150)', doc: 'The wait before a hovered trigger opens its panel.'), ApiParameter(name: 'panelMaxWidth', type: 'double', isRequired: false, isNamed: true, defaultValue: '560', doc: 'The largest panel width, in logical pixels.'), ApiParameter(name: 'semanticLabel', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The accessibility label of the menu.')])], properties: [], methods: [], values: []),
  'Oito2NavigationMenuItem': ApiEntry(kind: 'class', package: 'oito2_ui_extras', doc: 'An entry of an [Oito2NavigationMenu]: a link, or a trigger that opens\na panel built by [panelBuilder].', signature: '', constructors: [ApiConstructor(name: 'Oito2NavigationMenuItem', doc: 'Creates a navigation menu item.\n\nAsserts that [onPressed] and [panelBuilder] are not both given. An\nitem with neither is shown disabled.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'label', type: 'String', isRequired: true, isNamed: true, defaultValue: '', doc: 'The item text.'), ApiParameter(name: 'onPressed', type: 'VoidCallback?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called when a link item is pressed; null for a panel trigger.'), ApiParameter(name: 'panelBuilder', type: 'WidgetBuilder?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Builds the panel of a trigger item; null for a link.')])], properties: [], methods: [], values: []),
  'Oito2QrCode': ApiEntry(kind: 'class', package: 'oito2_ui_extras', doc: 'A QR code of [data], painted in [color] on [backgroundColor] with the\nstandard four-module quiet zone.\n\nThe defaults are black on white, which every scanner reads; custom\ncolors need strong contrast, with [color] darker than\n[backgroundColor]. A [centerImage], such as a logo, covers the middle\nof the modules; the error level is then [Oito2QrErrorLevel.high],\nwhich recovers the most covered modules, so the code still reads. When\n[data] doesn\'t fit, [errorBuilder] or a localized message shows\ninstead.', signature: '', constructors: [ApiConstructor(name: 'Oito2QrCode', doc: 'Creates a QR code.\n\nAsserts that [centerImageFraction] is above 0 and at most 0.3.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'data', type: 'String', isRequired: true, isNamed: true, defaultValue: '', doc: 'The encoded text, such as a link.'), ApiParameter(name: 'size', type: 'double', isRequired: false, isNamed: true, defaultValue: '160', doc: 'The width and height, quiet zone included.'), ApiParameter(name: 'errorLevel', type: 'Oito2QrErrorLevel', isRequired: false, isNamed: true, defaultValue: 'Oito2QrErrorLevel.medium', doc: 'The error correction level; ignored with [centerImage], which uses\n[Oito2QrErrorLevel.high].'), ApiParameter(name: 'color', type: 'Color', isRequired: false, isNamed: true, defaultValue: 'const Color(0xFF000000)', doc: 'The dark module color.'), ApiParameter(name: 'backgroundColor', type: 'Color', isRequired: false, isNamed: true, defaultValue: 'const Color(0xFFFFFFFF)', doc: 'The light module and quiet zone color.'), ApiParameter(name: 'roundedModules', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'false', doc: 'Whether dark modules are drawn as rounded squares.'), ApiParameter(name: 'centerImage', type: 'ImageProvider<Object>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'An image drawn in the middle, such as a logo.'), ApiParameter(name: 'centerImageFraction', type: 'double', isRequired: false, isNamed: true, defaultValue: '0.22', doc: 'The share of the module area\'s width cleared for the center image.'), ApiParameter(name: 'semanticLabel', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The accessibility label; defaults to the localized "QR code".'), ApiParameter(name: 'errorBuilder', type: 'WidgetBuilder?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Builds what shows when [data] doesn\'t fit in a QR code.')])], properties: [], methods: [], values: []),
  'Oito2QrErrorLevel': ApiEntry(kind: 'enum', package: 'oito2_ui_extras', doc: 'How much of an [Oito2QrCode] can be damaged or covered and still\nread, as error correction data takes more room.', signature: '', constructors: [], properties: [], methods: [], values: [ApiMember(name: 'low', signature: '', doc: 'About 7%.'), ApiMember(name: 'medium', signature: '', doc: 'About 15%.'), ApiMember(name: 'quartile', signature: '', doc: 'About 25%.'), ApiMember(name: 'high', signature: '', doc: 'About 30%.')]),
  'Oito2SignatureController': ApiEntry(kind: 'class', package: 'oito2_ui_extras', doc: 'The strokes of an [Oito2SignaturePad], with undo, clear and export.\n\nPositions are in the pad\'s logical pixels; [size] is the pad size the\nstrokes were drawn in, which the exports use.', signature: '', constructors: [ApiConstructor(name: 'Oito2SignatureController', doc: '', isConst: false, isFactory: false, parameters: [])], properties: [ApiMember(name: 'size', signature: 'Size', doc: 'The size of the pad, updated as it lays out; [toSvg] and [toImage]\nexport at this size.'), ApiMember(name: 'strokes', signature: 'List<List<({Offset position, double width})>>', doc: 'The strokes, in drawing order; neither the list nor its strokes can\nbe changed.'), ApiMember(name: 'isEmpty', signature: 'bool', doc: 'Whether nothing has been drawn.')], methods: [ApiMember(name: 'undo', signature: 'undo() → void', doc: 'Removes the last stroke, if any.'), ApiMember(name: 'clear', signature: 'clear() → void', doc: 'Removes every stroke.'), ApiMember(name: 'addStroke', signature: 'addStroke(List<({Offset position, double width})> stroke) → void', doc: 'Adds a copy of a whole [stroke], such as one of a saved signature.\n\nAn empty [stroke] is ignored.'), ApiMember(name: 'toSvg', signature: 'toSvg(Size? size, Color color) → String', doc: 'Returns the strokes as an SVG document of [size] (the pad size by\ndefault), one path per stroke segment so the width can vary.\n\nStrokes use the opaque RGB value of [color]; its alpha is ignored. A\nsingle-point stroke becomes a filled circle.'), ApiMember(name: 'toImage', signature: 'toImage(Color color, double pixelRatio) → Future<Image>', doc: 'Renders the strokes in [color] on a transparent background of the pad\n[size], at [pixelRatio] physical pixels per logical pixel.\n\nThe image is at least one pixel wide and tall. The caller owns the\nreturned image and must dispose it.'), ApiMember(name: 'toPngBytes', signature: 'toPngBytes(Color color, double pixelRatio) → Future<Uint8List?>', doc: 'Returns the strokes encoded as PNG bytes, or null when encoding\nfails; see [toImage].')], values: []),
  'Oito2SignaturePad': ApiEntry(kind: 'class', package: 'oito2_ui_extras', doc: 'An area to sign with a pointer, finger or pen.\n\nStrokes get thinner as the pointer moves faster, between [minWidth]\nand [maxWidth], like ink. A stylus\' pressure, when reported, makes\nthem wider. With [showActions] undo and clear buttons sit in a corner.\nAssistive technologies hear whether the pad is empty or signed.', signature: '', constructors: [ApiConstructor(name: 'Oito2SignaturePad', doc: 'Creates a signature pad.\n\nAsserts that [minWidth] is positive and not above [maxWidth].', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'controller', type: 'Oito2SignatureController', isRequired: true, isNamed: true, defaultValue: '', doc: 'The controller that holds the drawn strokes.'), ApiParameter(name: 'height', type: 'double', isRequired: false, isNamed: true, defaultValue: '180', doc: 'The pad height; it takes the available width.'), ApiParameter(name: 'color', type: 'Color?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The ink color; defaults to the theme\'s text color.'), ApiParameter(name: 'minWidth', type: 'double', isRequired: false, isNamed: true, defaultValue: '1.2', doc: 'The thinnest stroke.'), ApiParameter(name: 'maxWidth', type: 'double', isRequired: false, isNamed: true, defaultValue: '3.6', doc: 'The thickest stroke.'), ApiParameter(name: 'showActions', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether undo and clear buttons show.'), ApiParameter(name: 'placeholder', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The text shown on the empty pad; defaults to the localized "Sign\nhere".'), ApiParameter(name: 'semanticLabel', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The accessibility label; defaults to the localized "Signature".')])], properties: [], methods: [], values: []),
  'Oito2SignaturePoint': ApiEntry(kind: 'typedef', package: 'oito2_ui_extras', doc: 'A point of a signature stroke with the stroke width there.', signature: '({Offset position, double width})', constructors: [], properties: [], methods: [], values: []),
  'oito2QrModules': ApiEntry(kind: 'function', package: 'oito2_ui_extras', doc: 'The dark modules of the QR code of [data], as a square grid of\n[moduleCount] rows: `modules[row][column]` is true for a dark module.\n\nThrows an [ArgumentError] when [data] doesn\'t fit in a QR code at\n[errorLevel].', signature: 'oito2QrModules(String data, Oito2QrErrorLevel errorLevel) → ({int moduleCount, List<List<bool>> modules})', constructors: [], properties: [], methods: [], values: []),
  'Oito2DownloadTrigger': ApiEntry(kind: 'class', package: 'oito2_ui_files', doc: 'A button that saves a file built on demand with [Oito2Downloads].\n\nA tap awaits [data], showing a spinner, and saves the bytes as\n[fileName]. [onSaved] reports whether the file was saved, and [onError]\nreceives a failure of [data] or of saving. On platforms that can\'t\nsave files, the button is disabled and its tooltip says why.', signature: '', constructors: [ApiConstructor(name: 'Oito2DownloadTrigger', doc: 'Creates a download trigger.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'fileName', type: 'String', isRequired: true, isNamed: true, defaultValue: '', doc: 'The suggested file name.'), ApiParameter(name: 'data', type: 'Future<Uint8List> Function()', isRequired: true, isNamed: true, defaultValue: '', doc: 'Builds the file content when the button is activated.'), ApiParameter(name: 'mimeType', type: 'String?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The MIME type of the file, or null for a generic binary file.'), ApiParameter(name: 'label', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The button label; defaults to the localized "Download".'), ApiParameter(name: 'onSaved', type: 'ValueChanged<bool>?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called after a save with whether the file was saved.'), ApiParameter(name: 'onError', type: 'void Function(Object, StackTrace)?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Called when building or saving the file fails; without it the error\nis rethrown as an unhandled asynchronous error.'), ApiParameter(name: 'enabled', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether the button can be activated.')])], properties: [], methods: [], values: []),
  'Oito2Downloads': ApiEntry(kind: 'abstract class', package: 'oito2_ui_files', doc: 'Saves bytes as a file on the device: a download on the web, the\n"Save as" dialog on Linux, Windows and macOS.', signature: '', constructors: [ApiConstructor(name: 'Oito2Downloads', doc: '', isConst: false, isFactory: false, parameters: [])], properties: [ApiMember(name: 'isSupported', signature: 'static bool', doc: 'Whether this platform can save files: the web and desktop platforms,\nnot Android or iOS.')], methods: [ApiMember(name: 'save', signature: 'static save(String fileName, Uint8List bytes, String? mimeType) → Future<bool>', doc: 'Saves [bytes] as [fileName], typed as [mimeType] when given.\n\nReturns false when the user cancels the "Save as" dialog, and true\notherwise; a web download always returns true. Throws an\n[UnsupportedError] when not [isSupported].')], values: []),
  'Oito2FileDropTargetBuilder': ApiEntry(kind: 'typedef', package: 'oito2_ui_files', doc: 'Builds a widget that receives files dropped on [child]: [onHover]\nreports whether files are dragged over it, and [onDrop] receives the\ndropped files while [enabled].\n\nPass one to [Oito2FileDropZone.dropTargetBuilder] to receive drops from\nanother source than [oito2PlatformDropTarget].', signature: 'Widget Function({required Widget child, required bool enabled, required void Function(List<XFile>) onDrop, required void Function(bool) onHover})', constructors: [], properties: [], methods: [], values: []),
  'Oito2FileDropZone': ApiEntry(kind: 'class', package: 'oito2_ui_files', doc: 'A dashed box that opens the file chooser when activated and, where the\nplatform supports it, receives files dropped on it.\n\nThe chosen or dropped files go to [onFiles] unchecked; an\n`Oito2FileUploadController` checks them against its limits. [accept]\nfilters the file chooser. Drops come from [dropTargetBuilder], or from\n[oito2PlatformDropTarget] (the web, Linux, Windows and macOS) when it is\nnull, and pass every dropped file even when [multiple] is false.', signature: '', constructors: [ApiConstructor(name: 'Oito2FileDropZone', doc: 'Creates a file drop zone.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'onFiles', type: 'ValueChanged<List<XFile>>', isRequired: true, isNamed: true, defaultValue: '', doc: 'Receives the chosen or dropped files.'), ApiParameter(name: 'accept', type: 'List<XTypeGroup>', isRequired: false, isNamed: true, defaultValue: 'const []', doc: 'The file types the file chooser offers; empty offers every file.'), ApiParameter(name: 'multiple', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether several files can be chosen at once in the file chooser.'), ApiParameter(name: 'enabled', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether the zone opens the chooser and receives drops.'), ApiParameter(name: 'hint', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'A line under the title, such as the accepted types and sizes.'), ApiParameter(name: 'dropTargetBuilder', type: 'Oito2FileDropTargetBuilder?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The source of dropped files; null uses [oito2PlatformDropTarget].'), ApiParameter(name: 'minHeight', type: 'double', isRequired: false, isNamed: true, defaultValue: '160', doc: 'The smallest height of the zone, in logical pixels.')])], properties: [], methods: [], values: []),
  'Oito2FileRejection': ApiEntry(kind: 'enum', package: 'oito2_ui_files', doc: 'Why an [Oito2FileUploadController] refused a file.', signature: '', constructors: [], properties: [], methods: [], values: [ApiMember(name: 'type', signature: '', doc: 'The file type is not one of the accepted types.'), ApiMember(name: 'size', signature: '', doc: 'The file is larger than the size limit.'), ApiMember(name: 'count', signature: '', doc: 'The upload already holds the largest number of files.'), ApiMember(name: 'directory', signature: '', doc: 'The item is a directory, not a file.')]),
  'Oito2FileUpload': ApiEntry(kind: 'class', package: 'oito2_ui_files', doc: 'A file upload: an [Oito2FileDropZone] that adds files to [controller],\nthe files refused by the last addition with the reasons, and the list\nof accepted files with their size, a preview of images and a remove\nbutton.\n\nThe zone hint defaults to the accepted types and the size limit of the\ncontroller; the zone is disabled once the controller holds its largest\nnumber of files.', signature: '', constructors: [ApiConstructor(name: 'Oito2FileUpload', doc: 'Creates a file upload.', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'controller', type: 'Oito2FileUploadController', isRequired: true, isNamed: true, defaultValue: '', doc: 'The controller that holds the files and checks their limits.'), ApiParameter(name: 'hint', type: 'Widget?', isRequired: false, isNamed: true, defaultValue: '', doc: 'Replaces the default zone hint, which lists the accepted types and\nthe size limit.'), ApiParameter(name: 'showPreviews', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether image files show a thumbnail.'), ApiParameter(name: 'enabled', type: 'bool', isRequired: false, isNamed: true, defaultValue: 'true', doc: 'Whether files can be added and removed.'), ApiParameter(name: 'dropTargetBuilder', type: 'Oito2FileDropTargetBuilder?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The source of dropped files; see [Oito2FileDropZone.dropTargetBuilder].'), ApiParameter(name: 'zoneMinHeight', type: 'double', isRequired: false, isNamed: true, defaultValue: '160', doc: 'The smallest height of the drop zone, in logical pixels.')])], properties: [], methods: [], values: []),
  'Oito2FileUploadController': ApiEntry(kind: 'class', package: 'oito2_ui_files', doc: 'The files of a file upload, checked against the [accept]ed types,\n[maxFileSize] and [maxFiles] as they are added; directories dropped on\nan `Oito2FileDropZone` are always refused.\n\n[add] keeps the files that pass the checks and lists the others in\n[rejected], which holds the refusals of the last [add] only.', signature: '', constructors: [ApiConstructor(name: 'Oito2FileUploadController', doc: 'Creates a controller holding [files] at first, unchecked.\n\nAsserts that [maxFiles] and [maxFileSize], when given, are positive.', isConst: false, isFactory: false, parameters: [ApiParameter(name: 'accept', type: 'List<XTypeGroup>', isRequired: false, isNamed: true, defaultValue: 'const []', doc: 'The accepted file types; empty accepts every file.'), ApiParameter(name: 'maxFiles', type: 'int?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The largest number of files, or null for no limit.'), ApiParameter(name: 'maxFileSize', type: 'int?', isRequired: false, isNamed: true, defaultValue: '', doc: 'The largest file size, in bytes, or null for no limit.'), ApiParameter(name: 'files', type: 'Iterable<XFile>', isRequired: false, isNamed: true, defaultValue: 'const []', doc: '')])], properties: [ApiMember(name: 'rejected', signature: 'List<Oito2RejectedFile>', doc: 'The files refused by the last [add].'), ApiMember(name: 'canAddMore', signature: 'bool', doc: 'Whether more files can be added.')], methods: [ApiMember(name: 'add', signature: 'add(Iterable<XFile> incoming) → Future<void>', doc: 'Adds the files of [incoming] that pass the checks, in order, and\nlists the others in [rejected].\n\nReading the size of each file can take a moment, so this completes\nonce every file is checked. Nothing changes when the controller is\ndisposed meanwhile. A call made before an earlier one completes waits\nfor it, so the limits hold across both.'), ApiMember(name: 'remove', signature: 'remove(XFile file) → void', doc: 'Removes [file], if the controller holds it.'), ApiMember(name: 'clear', signature: 'clear() → void', doc: 'Removes every file and refusal.'), ApiMember(name: 'clearRejected', signature: 'clearRejected() → void', doc: 'Forgets the refusals of the last [add].')], values: []),
  'Oito2RejectedFile': ApiEntry(kind: 'class', package: 'oito2_ui_files', doc: 'A file an [Oito2FileUploadController] refused, with the reason.', signature: '', constructors: [ApiConstructor(name: 'Oito2RejectedFile', doc: 'Creates a record of [file] refused for [reason].', isConst: true, isFactory: false, parameters: [ApiParameter(name: 'file', type: 'XFile', isRequired: true, isNamed: false, defaultValue: '', doc: 'The refused file.'), ApiParameter(name: 'reason', type: 'Oito2FileRejection', isRequired: true, isNamed: false, defaultValue: '', doc: 'Why it was refused.')])], properties: [], methods: [], values: []),
  'oito2CanDropFiles': ApiEntry(kind: 'getter', package: 'oito2_ui_files', doc: 'Whether [oito2PlatformDropTarget] receives dropped files on this\nplatform: true on the web, Linux, Windows and macOS.', signature: 'bool', constructors: [], properties: [], methods: [], values: []),
  'oito2FileMatchesTypes': ApiEntry(kind: 'function', package: 'oito2_ui_files', doc: 'Whether [file] is one of the [accept]ed types.\n\nA type group matches when the file name ends with one of its\n`extensions` (ignoring case and a leading dot), or when the file\'s MIME\ntype is one of its `mimeTypes` or `webWildCards`, where `image/*`\nmatches every image type. No groups, or a group with none of those\nlists, accept every file.', signature: 'oito2FileMatchesTypes(XFile file, List<XTypeGroup> accept) → bool', constructors: [], properties: [], methods: [], values: []),
  'oito2PlatformDropTarget': ApiEntry(kind: 'function', package: 'oito2_ui_files', doc: 'The drop target of the platform: files dragged from the desktop onto\n[child], received through the browser on the web and through the\ndesktop_drop plugin on Linux, Windows and macOS; elsewhere, [child]\nalone, without drops.\n\nDropped directories are handed over with the files, marked so that an\n`Oito2FileUploadController` refuses them.', signature: 'oito2PlatformDropTarget(Widget child, bool enabled, ValueChanged<bool> onHover, ValueChanged<List<XFile>> onDrop) → Widget', constructors: [], properties: [], methods: [], values: []),
